	[19001] = {
		id = 19001,
		fmt = "#C0xFFF5D6#1. Players can send Red Packets or grab Red Packets in the guild. As there are a limited number of Red Packets, the fastest finger gets it first!",
		fmt_th = "#C0xFFF5D6#1. ผู้เล่นสามารถส่งอั่งเปาหรือคว้าอั่งเปาในกิลด์ เนื่องจากซองอั่งเปามีจำนวนจำกัด คนที่เร็วที่สุดจึงได้ไปก่อน!",
		fmt_en = "#C0xFFF5D6#1. Players can send Red Packets or grab Red Packets in the guild. As there are a limited number of Red Packets, the fastest finger gets it first!"
	},
	[19002] = {
		id = 19002,
		fmt = "#C0xFFF5D6#2. Guild Red Packets are automatically refreshed at 19:00 daily",
		fmt_th = "#C0xFFF5D6#2. Guild Red Packets จะรีเฟรชอัตโนมัติเวลา 19:00 น. ทุกวัน",
		fmt_en = "#C0xFFF5D6#2. Guild Red Packets are automatically refreshed at 19:00 daily"
	},
	[19003] = {
		id = 19003,
		fmt = "#C0xFFF5D6#3. Raising the level of the Red Packet Technology Institute can increase the amount and number of guild Red Rackets",
		fmt_th = "#C0xFFF5D6#3. การเพิ่มระดับของสถาบันเทคโนโลยีซองแดงสามารถเพิ่มจำนวนและจำนวนของแร็กเก็ตแดงกิลด์ได้",
		fmt_en = "#C0xFFF5D6#3. Raising the level of the Red Packet Technology Institute can increase the amount and number of guild Red Rackets"
	},
	[19004] = {
		id = 19004,
		fmt = "#C0xFFF5D6#4. Sending Red Packets and grabbing Red Packets require trainers to select manually.",
		fmt_th = "#C0xFFF5D6#4. การส่งซองอั่งเปาและการจับอั่งเปาต้องการให้ผู้ฝึกสอนต้องเลือกด้วยตนเอง",
