	},
	[19005] = {
		id = 19005,
		fmt = "#C0xFFF5D6#5. Trainers can also snatch the Red Packets that are given by themselves.",
		fmt_th = "#C0xFFF5D6#5. ผู้ฝึกสอนยังสามารถคว้าซองอั่งเปาที่ให้มาเองได้",
