	},
	[19006] = {
		id = 19006,
		fmt = "#C0xFFF5D6#6. The amount you get from Red Packets is random. It all depends on your luck!",
		fmt_th = "#C0xFFF5D6#6. จำนวนเงินที่คุณได้รับจากซองแดงเป็นการสุ่ม ทุกอย่างขึ้นอยู่กับโชคของคุณ!",
		fmt_en = "#C0xFFF5D6#6. The amount you get from Red Packets is random. It all depends on your luck!"
	},
	[19007] = {
		id = 19007,
		fmt = "#C0xFFF5D6#7. As the VIP level increases, the number of Red Packet that can be given or grabbed increases",
		fmt_th = "#C0xFFF5D6#7. เมื่อระดับ  VIP เพิ่มขึ้น จำนวนอั่งเปาที่สามารถให้หรือคว้าได้จะเพิ่มขึ้น",
		fmt_en = "#C0xFFF5D6#7. As the VIP level increases, the number of Red Packet that can be given or grabbed increases"
	},
	[19008] = {
		id = 19008,
		fmt = "#C0xFFF5D6#8. Red Packets sent by trainers are only valid for 24 hours. It disappears when expires and the remaining amount will not be returned",
		fmt_th = "#C0xFFF5D6#8. อั่งเปาที่ส่งโดยผู้ฝึกสอนจะมีอายุเพียง 24 ชั่วโมงเท่านั้น จะหายไปเมื่อหมดอายุและจะไม่คืนเงินส่วนที่เหลือ",
		fmt_en = "#C0xFFF5D6#8. Red Packets sent by trainers are only valid for 24 hours. It disappears when expires and the remaining amount will not be returned"
	},
	[20001] = {
		id = 20001,
		fmt = "Welcome to the Guild War! One season of Guild War is conducted once weekly, and each season has plenty of rewards to be won. Invite your comrades and fight together!",
		fmt_th = "ยินดีต้อนรับสู่สงครามกิลด์! หนึ่งฤดูกาลของสงครามกิลด์จะดำเนินการสัปดาห์ละครั้ง และแต่ละฤดูกาลมีรางวัลมากมายให้คว้า เชิญสหายของคุณและต่อสู้ด้วยกัน!",
		fmt_en = "Welcome to the Guild War! One season of Guild War is conducted once weekly, and each season has plenty of rewards to be won. Invite your comrades and fight together!"
	},
	[20002] = {
		id = 20002,
		fmt = "1. Guild War is conducted in two stages, the qualifying and final match: 4 days of qualifying match (Tuesday to Friday) and 1 day of final match (Saturday);",
		fmt_th = "1. สงครามกิลด์จะดำเนินการในสองขั้นตอน คือ รอบคัดเลือกและรอบชิงชนะเลิศ: 4 วันของการแข่งขันรอบคัดเลือก (วันอังคารถึงวันศุกร์) และ 1 วันของการแข่งขันรอบชิงชนะเลิศ (วันเสาร์);",
		fmt_en = "1. Guild War is conducted in two stages, the qualifying and final match: 4 days of qualifying match (Tuesday to Friday) and 1 day of final match (Saturday);"
	},
	[20003] = {
		id = 20003,
		fmt = "2. Daily registration time: #C0xF76B45#11:30-22:50",
		fmt_th = "2. เวลาลงทะเบียนรายวัน: #C0xF76B45#11:30-22:50",
		fmt_en = "2. Daily registration time: #C0xF76B45#11:30-22:50"
	},
	[20004] = {
		id = 20004,
		fmt = "3. Official daily start time of the tournament:    #C0xF76B45#23:00",
		fmt_th = "3. เวลาเริ่มต้นอย่างเป็นทางการรายวันของการแข่งขัน: #C0xF76B45#23:00",
		fmt_en = "3. Official daily start time of the tournament:    #C0xF76B45#23:00"
	},
	[20005] = {
		id = 20005,
		fmt = "4. Registration eligibility: Only players with trainer and guild level 40 and above can register. Those who have completed the registration can participate in the competition on the same day;",
		fmt_th = "4. คุณสมบัติในการลงทะเบียน: เฉพาะผู้เล่นที่มีเทรนเนอร์และกิลด์ระดับ 40 ขึ้นไปเท่านั้นที่สามารถลงทะเบียนได้ ผู้ที่ลงทะเบียนเสร็จแล้วสามารถเข้าร่วมการแข่งขันได้ในวันเดียวกัน",
		fmt_en = "4. Registration eligibility: Only players with trainer and guild level 40 and above can register. Those who have completed the registration can participate in the competition on the same day;"
	},
	[20006] = {
		id = 20006,
		fmt = "5. Players with VIP levels of 3 and above will be registered automatically half an hour before the start of the battle each day.",
		fmt_th = "5. ผู้เล่นที่มี  VIP ระดับ 3 ขึ้นไปจะถูกลงทะเบียนโดยอัตโนมัติครึ่งชั่วโมงก่อนเริ่มการต่อสู้ในแต่ละวัน",
		fmt_en = "5. Players with VIP levels of 3 and above will be registered automatically half an hour before the start of the battle each day."
	},
	[21001] = {
		id = 21001,
		fmt = "1. During the qualifiers, the type of battling Pokémons will be limited from Tuesday to Thursday. You may check the registration interface or the formation interface of the day for specific restrictions. There are no restrictions on the types of Pokémons on Friday;",
		fmt_th = "1. ระหว่างรอบคัดเลือก ประเภทของโปเกมอนต่อสู้จะถูกจำกัดตั้งแต่วันอังคารถึงวันพฤหัสบดี คุณสามารถตรวจสอบอินเทอร์เฟซการลงทะเบียนหรืออินเทอร์เฟซการก่อตัวของวันเพื่อดูข้อจำกัดเฉพาะ ไม่มีข้อจำกัดเกี่ยวกับประเภทของโปเกมอนในวันศุกร์",
		fmt_en = "1. During the qualifiers, the type of battling Pokémons will be limited from Tuesday to Thursday. You may check the registration interface or the formation interface of the day for specific restrictions. There are no restrictions on the types of Pokémons on Friday;"
	},
	[21002] = {
		id = 21002,
		fmt = "2. For rounds that limit the Pokémon type, the Pokémon can still join the battle as long as one of the types are allowed. Pokémons of the same evolution series are only allowed once a day;",
		fmt_th = "2. สำหรับรอบที่จำกัดประเภทโปเกมอน โปเกมอนยังสามารถเข้าร่วมการต่อสู้ได้ตราบเท่าที่อนุญาตให้มีประเภทใดประเภทหนึ่ง อนุญาตให้ใช้โปเกมอนในซีรีย์วิวัฒนาการเดียวกันได้วันละครั้งเท่านั้น",
		fmt_en = "2. For rounds that limit the Pokémon type, the Pokémon can still join the battle as long as one of the types are allowed. Pokémons of the same evolution series are only allowed once a day;"
	},
	[21003] = {
		id = 21003,
		fmt = "3. 2 teams of 3 Pokémons can be sent out for the qualifiers;",
		fmt_th = "3. สามารถส่งโปเกมอน 2 ทีมจาก 3 ตัวสำหรับรอบคัดเลือก",
		fmt_en = "3. 2 teams of 3 Pokémons can be sent out for the qualifiers;"
	},
	[21004] = {
		id = 21004,
		fmt = "4. After the first team is defeated, the second team can continue the battle in the next round;",
		fmt_th = "4. หลังจากที่ทีมแรกแพ้ ทีมที่สองสามารถสู้ต่อได้ในรอบต่อไป",
		fmt_en = "4. After the first team is defeated, the second team can continue the battle in the next round;"
	},
	[21005] = {
		id = 21005,
		fmt = "5. The tournament is conducted in brawl mode, where you will face players from other guilds (when there are too few remaining players, you may have fight against players from the same guild to decide the individual ranking);",
		fmt_th = "5. การแข่งขันจะดำเนินการในโหมดวิวาท ซึ่งคุณจะต้องเผชิญหน้ากับผู้เล่นจากกิลด์อื่น ๆ (เมื่อมีผู้เล่นเหลือน้อยเกินไป คุณอาจจะต้องต่อสู้กับผู้เล่นจากกิลด์เดียวกันเพื่อตัดสินอันดับของแต่ละคน)",
		fmt_en = "5. The tournament is conducted in brawl mode, where you will face players from other guilds (when there are too few remaining players, you may have fight against players from the same guild to decide the individual ranking);"
	},
	[21006] = {
		id = 21006,
		fmt = "6. The winner can advance to the next battle and continue to fight against the remaining opponents;",
		fmt_th = "6. ผู้ชนะสามารถเข้าสู่การต่อสู้ครั้งต่อไปและต่อสู้กับคู่ต่อสู้ที่เหลือต่อไป",
		fmt_en = "6. The winner can advance to the next battle and continue to fight against the remaining opponents;"
	},
	[21007] = {
		id = 21007,
		fmt = "7. HP and rage value remain after each battle;",
		fmt_th = "7. ค่า HP และ Rage ยังคงอยู่หลังจากการต่อสู้แต่ละครั้ง",
		fmt_en = "7. HP and rage value remain after each battle;"
	},
	[21008] = {
		id = 21008,
		fmt = "87.There's a point system in Guild War. The individual points are calculated as follows: 2 points are given for every victory, and for every loss, 1 point is given;",
		fmt_th = "87. มีระบบคะแนนในสงครามกิลด์ แต้มแต่ละแต้มจะคำนวณดังนี้: ให้ 2 แต้มสำหรับทุกชัยชนะ และทุกๆ การสูญเสีย จะได้รับ 1 แต้ม",
		fmt_en = "87.There's a point system in Guild War. The individual points are calculated as follows: 2 points are given for every victory, and for every loss, 1 point is given;"
	},
	[21009] = {
		id = 21009,
		fmt = "9. The final winner can increase the guild points and Battle Star for the guild. Battle Star can be used to adjust type bonus during the final battle;",
		fmt_th = "9. ผู้ชนะคนสุดท้ายสามารถเพิ่มคะแนนกิลด์และ Battle Star สำหรับกิลด์ได้ Battle Star สามารถใช้เพื่อปรับโบนัสประเภทระหว่างการต่อสู้ครั้งสุดท้าย",
		fmt_en = "9. The final winner can increase the guild points and Battle Star for the guild. Battle Star can be used to adjust type bonus during the final battle;"
	},
	[21010] = {
		id = 21010,
		fmt = "10. The daily ranking of the guild is determined by the total no. of points of the guild has earned on that day;",
		fmt_th = "10. อันดับรายวันของกิลด์จะถูกกำหนดโดยจำนวนทั้งหมด แต้มของกิลด์ที่ได้รับในวันนั้น",
		fmt_en = "10. The daily ranking of the guild is determined by the total no. of points of the guild has earned on that day;"
	},
	[21011] = {
		id = 21011,
		fmt = "11. Trainers of both sides can battle for 10 turns at most. If the winner is undecided at the end of the battle, the party with the highest % of remaining HP wins.",
		fmt_th = "11. ผู้ฝึกสอนทั้งสองฝ่ายสามารถต่อสู้ได้สูงสุด 10 เทิร์น ถ้าผู้ชนะไม่ถูกตัดสินเมื่อสิ้นสุดการต่อสู้ ปาร์ตี้ที่มี % สูงสุดของ HP ที่เหลืออยู่จะเป็นผู้ชนะ",
		fmt_en = "11. Trainers of both sides can battle for 10 turns at most. If the winner is undecided at the end of the battle, the party with the highest % of remaining HP wins."
	},
	[22001] = {
		id = 22001,
		fmt = "1. During the first 4 days of battle, the top 8 guilds competing in the Guild War will be qualified for the finals. All players who are eligible will be automatically qualified during the preparation period of the finals;",
		fmt_th = "1. ในช่วง 4 วันแรกของการต่อสู้ กิลด์ 8 อันดับแรกที่แข่งขันในสงครามกิลด์จะผ่านเข้ารอบชิงชนะเลิศ ผู้เล่นทุกคนที่มีสิทธิ์จะผ่านการคัดเลือกโดยอัตโนมัติในช่วงเตรียมการรอบชิงชนะเลิศ",
		fmt_en = "1. During the first 4 days of battle, the top 8 guilds competing in the Guild War will be qualified for the finals. All players who are eligible will be automatically qualified during the preparation period of the finals;"
	},
	[22002] = {
		id = 22002,
		fmt = "2. In the finals, Pokémons of all types can enter the battle;",
		fmt_th = "2. ในรอบชิงชนะเลิศ โปเกมอนทุกประเภทสามารถเข้าสู่การต่อสู้ได้",
		fmt_en = "2. In the finals, Pokémons of all types can enter the battle;"
	},
	[22003] = {
		id = 22003,
		fmt = "3. The finals will be conducted in Guild VS Guild and elimination format. The tournament ends when the winner emerges;",
		fmt_th = "3. รอบชิงชนะเลิศจะดำเนินการในกิลด์ VS กิลด์และรูปแบบการกำจัด การแข่งขันจะสิ้นสุดลงเมื่อผู้ชนะปรากฏตัว",
		fmt_en = "3. The finals will be conducted in Guild VS Guild and elimination format. The tournament ends when the winner emerges;"
	},
	[22004] = {
		id = 22004,
		fmt = "4. The battle mode of the finals tag match format between guilds. Players can use 3 Pokémon teams to compete and each team can only send up to 4 Pokémons to battle;",
		fmt_th = "4. โหมดการต่อสู้ของรูปแบบการจับคู่แท็กรอบชิงชนะเลิศระหว่างกิลด์ ผู้เล่นสามารถใช้โปเกมอนได้ 3 ทีมเพื่อแข่งขัน และแต่ละทีมสามารถส่งโปเกมอนไปต่อสู้ได้สูงสุด 4 ตัวเท่านั้น",
		fmt_en = "4. The battle mode of the finals tag match format between guilds. Players can use 3 Pokémon teams to compete and each team can only send up to 4 Pokémons to battle;"
	},
	[22005] = {
		id = 22005,
		fmt = "5. When two guilds fight against each other, according to the match sequence, the winning team will enter in the next match, while the losing team eliminated. This continues until all the teams of guild are completely defeated, and the other party wins;",
		fmt_th = "5. เมื่อสองกิลด์ต่อสู้กันเองตามลำดับการแข่งขัน ทีมที่ชนะจะเข้าสู่การแข่งขันนัดถัดไป ในขณะที่ทีมที่แพ้ตกรอบ สิ่งนี้จะดำเนินต่อไปจนกว่าทุกทีมในกิลด์จะพ่ายแพ้อย่างสมบูรณ์ และอีกฝ่ายเป็นฝ่ายชนะ",
		fmt_en = "5. When two guilds fight against each other, according to the match sequence, the winning team will enter in the next match, while the losing team eliminated. This continues until all the teams of guild are completely defeated, and the other party wins;"
	},
	[22006] = {
		id = 22006,
		fmt = "6. The winning guild can continue to participate in battles against winning guilds until a winner emerges;",
		fmt_th = "6. กิลด์ที่ชนะสามารถเข้าร่วมการต่อสู้กับกิลด์ที่ชนะต่อไปได้จนกว่าจะมีผู้ชนะ",
		fmt_en = "6. The winning guild can continue to participate in battles against winning guilds until a winner emerges;"
	},
	[22007] = {
		id = 22007,
		fmt = "7. The Pokémon statuses of the entire final series will remain. Even if you win, the Pokémons' HP will not be recovered during the battle against the next winning guild, and the defeated Pokémons will not revive.",
		fmt_th = "7. สถานะของโปเกมอนในซีรีย์สุดท้ายทั้งหมดจะยังคงอยู่ แม้ว่าคุณจะชนะ HP ของโปเกมอนจะไม่ฟื้นระหว่างการต่อสู้กับกิลด์ที่ชนะครั้งต่อไป และโปเกมอนที่พ่ายแพ้จะไม่ฟื้นคืนชีพ",
		fmt_en = "7. The Pokémon statuses of the entire final series will remain. Even if you win, the Pokémons' HP will not be recovered during the battle against the next winning guild, and the defeated Pokémons will not revive."
	},
	[22008] = {
		id = 22008,
		fmt = "8. After the final fight of Guild Battle, guilds can earn a lot of bonus points according to the ranking.",
		fmt_th = "8. หลังจากการต่อสู้กิลด์ครั้งสุดท้าย กิลด์จะได้รับคะแนนโบนัสมากมายตามอันดับ",
		fmt_en = "8. After the final fight of Guild Battle, guilds can earn a lot of bonus points according to the ranking."
	},
	[22101] = {
		id = 22101,
		fmt = "1. During the qualifiers, the guild that wins the final victory at the end of the day can get a Battle Star;",
		fmt_th = "1. ระหว่างรอบคัดเลือก กิลด์ที่ชนะชัยชนะครั้งสุดท้ายเมื่อสิ้นสุดวันจะได้รับ Battle Star",
		fmt_en = "1. During the qualifiers, the guild that wins the final victory at the end of the day can get a Battle Star;"
	},
	[22102] = {
		id = 22102,
		fmt = "2. Before the start of the finals, the administrator (Leader/Assistant Leader) of the Battle Star Guild can use Battle Star to set the bonus attributes and abilities for the finals;",
		fmt_th = "2. ก่อนเริ่มรอบชิงชนะเลิศ ผู้ดูแลระบบ (ผู้นำ/ผู้ช่วยหัวหน้า) ของกิลด์ Battle Star สามารถใช้ Battle Star เพื่อกำหนดคุณสมบัติโบนัสและความสามารถสำหรับรอบชิงชนะเลิศ",
		fmt_en = "2. Before the start of the finals, the administrator (Leader/Assistant Leader) of the Battle Star Guild can use Battle Star to set the bonus attributes and abilities for the finals;"
	},
	[22103] = {
		id = 22103,
		fmt = "3. One Battle Star will be used after setting successfully, and the setting is irreversible;",
		fmt_th = "3. หนึ่ง Battle Star จะถูกใช้หลังจากการตั้งค่าสำเร็จ และการตั้งค่านี้ไม่สามารถย้อนกลับได้",
		fmt_en = "3. One Battle Star will be used after setting successfully, and the setting is irreversible;"
	},
	[22104] = {
		id = 22104,
		fmt = "4. After setting is completed, the change in ability is effective for all Pokémons entering the finals",
		fmt_th = "4. หลังจากการตั้งค่าเสร็จสิ้น การเปลี่ยนแปลงความสามารถจะมีผลกับโปเกมอนทั้งหมดที่เข้าสู่รอบชิงชนะเลิศ",
		fmt_en = "4. After setting is completed, the change in ability is effective for all Pokémons entering the finals"
	},
	[22201] = {
		id = 22201,
		fmt = "1. Throughout the Guild War, in each battle, all Pokémons entering the battle for the first time can get a certain bonus in their ATK, DEF and Speed stats;",
		fmt_th = "1. ตลอดสงครามกิลด์ ในแต่ละการต่อสู้ โปเกมอนทั้งหมดที่เข้าร่วมการต่อสู้เป็นครั้งแรกจะได้รับโบนัสในสถิติ ATK, DEF และความเร็ว",
		fmt_en = "1. Throughout the Guild War, in each battle, all Pokémons entering the battle for the first time can get a certain bonus in their ATK, DEF and Speed stats;"
	},
	[22202] = {
		id = 22202,
		fmt = "2. As the battle continues, the buff effect will graduate reduce and the Pokémon will become weaker and more lethargic in battle;",
		fmt_th = "2. เมื่อการต่อสู้ดำเนินไป ผลของบัฟจะค่อยๆ ลดลง และโปเกมอนจะอ่อนแอลงและเฉื่อยชามากขึ้นในการต่อสู้",
		fmt_en = "2. As the battle continues, the buff effect will graduate reduce and the Pokémon will become weaker and more lethargic in battle;"
	},
	[22203] = {
		id = 22203,
		fmt = "3. In each battle, the stats of the Pokémons in the team such as ATK, DEF, SPD, and HP recovery will decrease continuously.",
		fmt_th = "3. ในแต่ละการต่อสู้ สถานะของโปเกมอนในทีม เช่น ATK, DEF, SPD และการฟื้นฟู HP จะลดลงอย่างต่อเนื่อง",
		fmt_en = "3. In each battle, the stats of the Pokémons in the team such as ATK, DEF, SPD, and HP recovery will decrease continuously."
	},
	[22301] = {
		id = 22301,
		fmt = "1. During the registration period of the finals (11:30-22:50 on Saturday), players can make a bet on the outcome of the match;",
		fmt_th = "1. ในช่วงการลงทะเบียนรอบชิงชนะเลิศ (11:30-22:50 น. ในวันเสาร์) ผู้เล่นสามารถเดิมพันผลการแข่งขันได้",
		fmt_en = "1. During the registration period of the finals (11:30-22:50 on Saturday), players can make a bet on the outcome of the match;"
	},
	[22302] = {
		id = 22302,
		fmt = "2. Place a bet on the champion that is no higher than 1,000,000 coins. The higher the odds, the greater the returns.",
		fmt_th = "2. วางเดิมพันแชมป์เปี้ยนที่มีมูลค่าไม่เกิน 1,000,000 เหรียญ ยิ่งโอกาสสูง ผลตอบแทนยิ่งสูง",
		fmt_en = "2. Place a bet on the champion that is no higher than 1,000,000 coins. The higher the odds, the greater the returns."
	},
	[22303] = {
		id = 22303,
		fmt = "3. When the tournament ends, rewards will all be sent via mail. Those who have guessed the champion correctly will receive rewards according to the odds, and if the contestant wins the second place, you get half of the bets you placed",
		fmt_th = "3. เมื่อการแข่งขันสิ้นสุดลง รางวัลทั้งหมดจะถูกส่งทางไปรษณีย์ ผู้ที่ทายแชมป์ได้ถูกต้องจะได้รับรางวัลตามอัตราต่อรอง และหากผู้เข้าแข่งขันชนะอันดับที่ 2 คุณจะได้รับเงินเดิมพันครึ่งหนึ่งที่คุณวาง",
		fmt_en = "3. When the tournament ends, rewards will all be sent via mail. Those who have guessed the champion correctly will receive rewards according to the odds, and if the contestant wins the second place, you get half of the bets you placed"
	},
	[23001] = {
		id = 23001,
		fmt = "1. After the tournament ends, all rewards will be sent via mail;",
		fmt_th = "1. หลังจากสิ้นสุดการแข่งขัน รางวัลทั้งหมดจะถูกส่งทางไปรษณีย์",
		fmt_en = "1. After the tournament ends, all rewards will be sent via mail;"
	},
	[23002] = {
		id = 23002,
		fmt = "2. Daily contest includes participation rewards, individual victory rewards and guild ranking rewards. For guild rewards. only participating members of the guild will receive the rewards;",
		fmt_th = "2. การแข่งขันรายวันรวมถึงรางวัลการเข้าร่วม รางวัลชัยชนะส่วนบุคคล และรางวัลอันดับกิลด์ สำหรับรางวัลกิลด์ เฉพาะสมาชิกที่เข้าร่วมกิลด์เท่านั้นที่จะได้รับรางวัล",
		fmt_en = "2. Daily contest includes participation rewards, individual victory rewards and guild ranking rewards. For guild rewards. only participating members of the guild will receive the rewards;"
	},
	[23003] = {
		id = 23003,
		fmt = "3. The contestants of both qualifiers and finals will receive a participation reward;",
		fmt_th = "3. ผู้เข้าแข่งขันทั้งในรอบคัดเลือกและรอบชิงชนะเลิศจะได้รับรางวัลการเข้าร่วม",
		fmt_en = "3. The contestants of both qualifiers and finals will receive a participation reward;"
	},
	[23004] = {
		id = 23004,
		fmt = "4. Individual victory rewards are given in the Guild War Honorary Box. Trainers will get one box for each victory, and up to 6 boxes a day;",
		fmt_th = "4. รางวัลชัยชนะส่วนบุคคลจะมอบให้ในกล่องเกียรติยศสงครามกิลด์ ผู้ฝึกสอนจะได้รับหนึ่งกล่องสำหรับชัยชนะแต่ละครั้ง และมากถึง 6 กล่องต่อวัน",
		fmt_en = "4. Individual victory rewards are given in the Guild War Honorary Box. Trainers will get one box for each victory, and up to 6 boxes a day;"
	},
	[23005] = {
		id = 23005,
		fmt = "5. Please see the following reward display for the details of Guild Ranking Rewards",
		fmt_th = "5. โปรดดูการแสดงรางวัลต่อไปนี้สำหรับรายละเอียดของรางวัลอันดับกิลด์",
		fmt_en = "5. Please see the following reward display for the details of Guild Ranking Rewards"
	},
	[24001] = {
		id = 24001,
		fmt = "#C0xFFF5D6#1. There are 2 series of tournaments per week. Each match lasts for 2 days, starting on Monday and Friday.",
		fmt_th = "#C0xFFF5D6#1. มีการแข่งขัน 2 ชุดต่อสัปดาห์ แต่ละแมตช์มีระยะเวลา 2 วัน เริ่มตั้งแต่วันจันทร์และวันศุกร์",
		fmt_en = "#C0xFFF5D6#1. There are 2 series of tournaments per week. Each match lasts for 2 days, starting on Monday and Friday."
	},
	[24002] = {
		id = 24002,
		fmt = "#C0xFFF5D6#2. Each season of tournament will match trainers based on their strength and number of participants of several servers.",
		fmt_th = "#C0xFFF5D6#2. แต่ละฤดูกาลของทัวร์นาเมนต์จะจับคู่ผู้ฝึกสอนตามความแข็งแกร่งและจำนวนผู้เข้าร่วมจากหลายเซิร์ฟเวอร์",
		fmt_en = "#C0xFFF5D6#2. Each season of tournament will match trainers based on their strength and number of participants of several servers."
	},
	[24003] = {
		id = 24003,
		fmt = "#C0xFFF5D6#3. Registration period: Day 1 of each series at 05:00-18:50",
		fmt_th = "#C0xFFF5D6#3. ระยะเวลาลงทะเบียน : วันที่ 1 ของแต่ละชุด เวลา 05:00-18:50 น.",
		fmt_en = "#C0xFFF5D6#3. Registration period: Day 1 of each series at 05:00-18:50"
	},
	[24004] = {
		id = 24004,
		fmt = "#C0xFFF5D6#4. Starting time: 19:00",
		fmt_th = "#C0xFFF5D6#4. เริ่มเวลา: 19:00 น.",
		fmt_en = "#C0xFFF5D6#4. Starting time: 19:00"
	},
	[24005] = {
		id = 24005,
		fmt = "#C0xFFF5D6#5. 12 Pokémons are to be selected during the registration, and can be changed freely before the game starts officially every day",
		fmt_th = "#C0xFFF5D6#5. ให้เลือกโปเกมอน 12 ตัวระหว่างการลงทะเบียน และสามารถเปลี่ยนแปลงได้อย่างอิสระก่อนเริ่มเกมอย่างเป็นทางการทุกวัน",
		fmt_en = "#C0xFFF5D6#5. 12 Pokémons are to be selected during the registration, and can be changed freely before the game starts officially every day"
	},
	[24006] = {
		id = 24006,
		fmt = "#C0xFFF5D6#6. Each season of tournament are conducted in 3 stages, the qualifiers, top 8 matches, and championship.",
		fmt_th = "#C0xFFF5D6#6. แต่ละฤดูกาลของการแข่งขันจะแบ่งออกเป็น 3 ด่าน ได้แก่ รอบคัดเลือก, 8 อันดับแรก และการแข่งขันชิงแชมป์",
		fmt_en = "#C0xFFF5D6#6. Each season of tournament are conducted in 3 stages, the qualifiers, top 8 matches, and championship."
	},
	[24007] = {
		id = 24007,
		fmt = "#C0xFFF5D6#7. Each qualifying match lasts for 4 minutes, while each of the quarterfinal and the championship match lasts for 5 minutes. Players are not allowed to change their line-up 1 minute before the start of the match.",
		fmt_th = "#C0xFFF5D6#7. การแข่งขันรอบคัดเลือกแต่ละนัดจะใช้เวลา 4 นาที ในขณะที่แต่ละรอบก่อนรองชนะเลิศและการแข่งขันชิงแชมป์จะใช้เวลา 5 นาที ไม่อนุญาตให้ผู้เล่นเปลี่ยนรายชื่อก่อนเริ่มการแข่งขัน 1 นาที",
		fmt_en = "#C0xFFF5D6#7. Each qualifying match lasts for 4 minutes, while each of the quarterfinal and the championship match lasts for 5 minutes. Players are not allowed to change their line-up 1 minute before the start of the match."
	},
	[24008] = {
		id = 24008,
		fmt = "#C0xFFF5D6#8. VIP3 and above can be automatically registered.",
		fmt_th = "#C0xFFF5D6#8.  VIP 3 ขึ้นไป สามารถลงทะเบียนได้อัตโนมัติ",
		fmt_en = "#C0xFFF5D6#8. VIP3 and above can be automatically registered."
	},
	[25001] = {
		id = 25001,
		fmt = "#C0xFFF5D6#1. Get 1 Gold Chest for each victory and 1 Silver Chest for each defeat.",
		fmt_th = "#C0xFFF5D6#1. รับ 1 กล่องทองคำสำหรับชัยชนะแต่ละครั้ง และ 1 กล่องเงินสำหรับการพ่ายแพ้แต่ละครั้ง",
		fmt_en = "#C0xFFF5D6#1. Get 1 Gold Chest for each victory and 1 Silver Chest for each defeat."
	},
	[25002] = {
		id = 25002,
		fmt = "#C0xFFF5D6#2. At the end of each tournament season, ranking rewards will be given based on your ranking.",
		fmt_th = "#C0xFFF5D6#2. ในตอนท้ายของแต่ละฤดูกาลการแข่งขัน รางวัลการจัดอันดับจะมอบให้ตามอันดับของคุณ",
		fmt_en = "#C0xFFF5D6#2. At the end of each tournament season, ranking rewards will be given based on your ranking."
	},
	[25003] = {
		id = 25003,
		fmt = "#C0xFFF5D6#3. You can get various rare rewards from opening the chest.",
		fmt_th = "#C0xFFF5D6#3. คุณสามารถรับรางวัลหายากต่างๆ ได้จากการเปิดหีบ",
		fmt_en = "#C0xFFF5D6#3. You can get various rare rewards from opening the chest."
	},
	[25004] = {
		id = 25004,
		fmt = "#C0xFFF5D6#4. Ranking rewards will be given via mail at the end of the tournament season",
		fmt_th = "#C0xFFF5D6#4. รางวัลอันดับจะมอบให้ทางไปรษณีย์เมื่อสิ้นสุดฤดูกาลการแข่งขัน",
		fmt_en = "#C0xFFF5D6#4. Ranking rewards will be given via mail at the end of the tournament season"
	},
	[26001] = {
		id = 26001,
		fmt = "#C0xFFF5D6#1. The qualifier adopts a point eliminated system",
		fmt_th = "#C0xFFF5D6#1. คัดเลือกใช้ระบบกำจัดจุด",
		fmt_en = "#C0xFFF5D6#1. The qualifier adopts a point eliminated system"
	},
	[26002] = {
		id = 26002,
		fmt = "#C0xFFF5D6#2. There are 3 rounds of qualifiers, 2 rounds on the first day and 1 on the second day. There will be 4 rounds of 12 matches, each lasting 4 minutes.",
		fmt_th = "#C0xFFF5D6#2. รอบคัดเลือกมี 3 รอบ วันแรก 2 รอบ และวันที่สอง 1 รอบ จะมี 4 รอบ 12 แมตช์ แต่ละครั้งกินเวลา 4 นาที",
		fmt_en = "#C0xFFF5D6#2. There are 3 rounds of qualifiers, 2 rounds on the first day and 1 on the second day. There will be 4 rounds of 12 matches, each lasting 4 minutes."
	},
	[26003] = {
		id = 26003,
		fmt = "#C0xFFF5D6#3. Trainers get the corresponding number of points for entering each match.",
		fmt_th = "#C0xFFF5D6#3. ผู้ฝึกสอนจะได้รับคะแนนเท่ากันในการเข้าแข่งขันแต่ละนัด",
		fmt_en = "#C0xFFF5D6#3. Trainers get the corresponding number of points for entering each match."
	},
	[26004] = {
		id = 26004,
		fmt = "#C0xFFF5D6#4. Points earned as well as the number of wins and losses are carried over to every qualifiers match. A total of 5 defeats will result in elimination.",
		fmt_th = "#C0xFFF5D6#4. คะแนนที่ได้รับรวมถึงจำนวนการชนะและแพ้จะถูกโอนไปยังการแข่งขันรอบคัดเลือกทุกนัด การแพ้ทั้งหมด 5 ครั้งจะส่งผลให้ถูกคัดออก",
		fmt_en = "#C0xFFF5D6#4. Points earned as well as the number of wins and losses are carried over to every qualifiers match. A total of 5 defeats will result in elimination."
	},
	[26005] = {
		id = 26005,
		fmt = "#C0xFFF5D6#5. Pokémons cannot be sent to battle multiple times for single-round matches, but the same Pokémon can be sent for battle between different rounds",
		fmt_th = "#C0xFFF5D6#5. ไม่สามารถส่งโปเกมอนไปต่อสู้หลายครั้งสำหรับการแข่งขันรอบเดียว แต่สามารถส่งโปเกมอนตัวเดียวกันไปต่อสู้ระหว่างรอบที่แตกต่างกันได้",
		fmt_en = "#C0xFFF5D6#5. Pokémons cannot be sent to battle multiple times for single-round matches, but the same Pokémon can be sent for battle between different rounds"
	},
	[27001] = {
		id = 27001,
		fmt = "#C0xFFF5D6#1. After the qualifiers, the top 64 will be compete for top 8 and the top 8 will complete in 8 different battlefields to advance further.",
		fmt_th = "#C0xFFF5D6#1. หลังจากรอบคัดเลือก 64 อันดับแรกจะแข่งขันกันเพื่อชิง 8 อันดับแรก และ 8 อันดับแรกจะเสร็จสิ้นใน 8 สนามรบที่แตกต่างกันเพื่อก้าวต่อไป",
		fmt_en = "#C0xFFF5D6#1. After the qualifiers, the top 64 will be compete for top 8 and the top 8 will complete in 8 different battlefields to advance further."
	},
	[27002] = {
		id = 27002,
		fmt = "#C0xFFF5D6#2. The top 8 selection tournament will be conducted in the elimination format, including 3 stages of matches, such as top 32, top 16, and top 8 matches",
		fmt_th = "#C0xFFF5D6#2. การแข่งขันคัดเลือก 8 อันดับแรกจะดำเนินการในรูปแบบการคัดออก ได้แก่ การแข่งขัน 3 ระยะ เช่น 32 อันดับแรก, 16 อันดับแรก และ 8 อันดับแรก",
		fmt_en = "#C0xFFF5D6#2. The top 8 selection tournament will be conducted in the elimination format, including 3 stages of matches, such as top 32, top 16, and top 8 matches"
	},
	[27003] = {
		id = 27003,
		fmt = "#C0xFFF5D6#3. Duration of each match is 5 minutes",
		fmt_th = "#C0xFFF5D6#3. ระยะเวลาของแต่ละแมตช์คือ 5 นาที",
		fmt_en = "#C0xFFF5D6#3. Duration of each match is 5 minutes"
	},
	[27004] = {
		id = 27004,
		fmt = "#C0xFFF5D6#4. Pokémons cannot be used repeatedly",
		fmt_th = "#C0xFFF5D6#4. โปเกมอนไม่สามารถใช้ซ้ำได้",
