	[28001] = {
		id = 28001,
		fmt = "#C0xFFF5D6#1. The winner of the top 8 matches is eligible to enter the championship.",
		fmt_th = "#C0xFFF5D6#1. ผู้ชนะจากการแข่งขัน 8 อันดับแรกมีสิทธิ์เข้าร่วมการแข่งขันชิงแชมป์",
		fmt_en = "#C0xFFF5D6#1. The winner of the top 8 matches is eligible to enter the championship."
