	[28002] = {
		id = 28002,
		fmt = "#C0xFFF5D6#2. The championship tournament will be conducted in the elimination format, including 3 stages of matches, such as quarterfinals, semifinals, finals",
		fmt_th = "#C0xFFF5D6#2. การแข่งขันชิงแชมป์จะจัดในรูปแบบการคัดออก ได้แก่ การแข่งขัน 3 ระยะ เช่น รอบก่อนรองชนะเลิศ, รอบรองชนะเลิศ, รอบชิงชนะเลิศ",
