	[28003] = {
		id = 28003,
		fmt = "#C0xFFF5D6#3. Duration of each match is 5 minutes",
		fmt_th = "#C0xFFF5D6#3. ระยะเวลาของแต่ละแมตช์คือ 5 นาที",
		fmt_en = "#C0xFFF5D6#3. Duration of each match is 5 minutes"
