	[28004] = {
		id = 28004,
		fmt = "#C0xFFF5D6#4. Pokémons cannot be used repeatedly",
		fmt_th = "#C0xFFF5D6#4. โปเกมอนไม่สามารถใช้ซ้ำได้",
		fmt_en = "#C0xFFF5D6#4. Pokémons cannot be used repeatedly"
