	[29001] = {
		id = 29001,
		fmt = "#C0xFFF5D6#1. The qualifiers, top 8 matches, and championship are all conducted in a 3v3 tag match format.",
		fmt_th = "#C0xFFF5D6#1. การแข่งขันรอบคัดเลือก การแข่งขัน 8 อันดับแรก และการแข่งขันชิงแชมป์ทั้งหมดดำเนินการในรูปแบบการแข่งขันแท็ก 3 ต่อ 3",
		fmt_en = "#C0xFFF5D6#1. The qualifiers, top 8 matches, and championship are all conducted in a 3v3 tag match format."
	},
	[29002] = {
		id = 29002,
		fmt = "C0xFFF5D6#2. When the Pokémons are in battle, the trainer with the highest first move points makes the first move. If both trainers have the same first move points, the one with the higher combat power makes the first move.",
		fmt_th = "C0xFFF5D6#2. เมื่อโปเกมอนอยู่ในสนามรบ ผู้ฝึกสอนที่มีคะแนนการเคลื่อนไหวแรกสูงสุดจะทำการเคลื่อนไหวครั้งแรก หากผู้ฝึกสอนทั้งสองมีจุดเคลื่อนที่แรกเท่ากัน ผู้ที่มีอำนาจการต่อสู้สูงกว่าจะเป็นผู้ดำเนินการครั้งแรก",
		fmt_en = "C0xFFF5D6#2. When the Pokémons are in battle, the trainer with the highest first move points makes the first move. If both trainers have the same first move points, the one with the higher combat power makes the first move."
	},
	[29003] = {
		id = 29003,
		fmt = "#C0xFFF5D6#3. When two Pokémons battle against each other, the maximum no. of turns is 10.",
		fmt_th = "#C0xFFF5D6#3. เมื่อโปเกมอนสองตัวต่อสู้กันเอง จำนวนสูงสุด ของเทิร์นคือ 10",
		fmt_en = "#C0xFFF5D6#3. When two Pokémons battle against each other, the maximum no. of turns is 10."
	},
	[29004] = {
		id = 29004,
		fmt = "#C0xFFF5D6#4. At the end of the 10th rounds, if the winner is still undecided, the party with the highest percentage of remaining HP wins.",
		fmt_th = "#C0xFFF5D6#4. เมื่อสิ้นสุดรอบที่ 10 หากผู้ชนะยังไม่ตัดสินใจ ปาร์ตี้ที่มีเปอร์เซ็นต์ HP สูงสุดที่เหลืออยู่จะเป็นผู้ชนะ",
		fmt_en = "#C0xFFF5D6#4. At the end of the 10th rounds, if the winner is still undecided, the party with the highest percentage of remaining HP wins."
	},
	[29005] = {
		id = 29005,
		fmt = "#C0xFFF5D6#5. Finally, the side with the surviving Pokémon wins.",
		fmt_th = "#C0xFFF5D6#5. ในที่สุด ฝ่ายที่มีโปเกมอนที่รอดตายจะเป็นฝ่ายชนะ",
		fmt_en = "#C0xFFF5D6#5. Finally, the side with the surviving Pokémon wins."
	},
	[30001] = {
		id = 30001,
		fmt = "#C0xFFF5D6#1. Trainers can place a bet on whether their number of victories in the qualifiers will be an odd or even number.",
		fmt_th = "#C0xFFF5D6#1. ผู้ฝึกสอนสามารถวางเดิมพันได้ว่าจำนวนชัยชนะของพวกเขาในรอบคัดเลือกจะเป็นเลขคี่หรือคู่",
		fmt_en = "#C0xFFF5D6#1. Trainers can place a bet on whether their number of victories in the qualifiers will be an odd or even number."
	},
	[30002] = {
		id = 30002,
		fmt = "#C0xFFF5D6#2. You can bet on the winner of the server's top 64 trainers in combat power ranking on the next day.",
		fmt_th = "#C0xFFF5D6#2. คุณสามารถเดิมพันผู้ชนะของผู้ฝึกสอน 64 อันดับแรกของเซิร์ฟเวอร์ในการจัดอันดับพลังการต่อสู้ในวันถัดไป",
		fmt_en = "#C0xFFF5D6#2. You can bet on the winner of the server's top 64 trainers in combat power ranking on the next day."
	},
	[30003] = {
		id = 30003,
		fmt = "#C0xFFF5D6#3. Place a bet on the champion. The higher the odds, the greater the returns. You get to win up to 1,500,000 coins each season",
		fmt_th = "#C0xFFF5D6#3. วางเดิมพันแชมป์ ยิ่งโอกาสสูง ผลตอบแทนยิ่งสูง คุณจะได้รับมากถึง 1,500,000 เหรียญในแต่ละฤดูกาล",
		fmt_en = "#C0xFFF5D6#3. Place a bet on the champion. The higher the odds, the greater the returns. You get to win up to 1,500,000 coins each season"
	},
	[30004] = {
		id = 30004,
		fmt = "#C0xFFF5D6#4. If the contestant you bet on enters the semifinals, you will receive 1.5 times of the bet. Otherwise, you will receive half of your bet.",
		fmt_th = "#C0xFFF5D6#4. หากผู้เข้าแข่งขันที่คุณเดิมพันเข้าสู่รอบรองชนะเลิศ คุณจะได้รับ 1.5 เท่าของเงินเดิมพัน มิฉะนั้น คุณจะได้รับเงินเดิมพันครึ่งหนึ่ง",
		fmt_en = "#C0xFFF5D6#4. If the contestant you bet on enters the semifinals, you will receive 1.5 times of the bet. Otherwise, you will receive half of your bet."
	},
	[30005] = {
		id = 30005,
		fmt = "#C0xFFF5D6#5. Ranking reward are as follows:",
		fmt_th = "#C0xFFF5D6#5. รางวัลอันดับมีดังนี้",
		fmt_en = "#C0xFFF5D6#5. Ranking reward are as follows:"
	},
	[31001] = {
		id = 31001,
		fmt = "#C0x08ED1F#The Pokémons found a land rich in ore. It's said that ores can be exchanged for rich rewards in a shop on the land, and since then Mine War has begun among the trainers.",
		fmt_th = "#C0x08ED1F#โปเกมอนพบดินแดนที่อุดมไปด้วยแร่ ว่ากันว่าแร่สามารถแลกเปลี่ยนเป็นรางวัลมากมายในร้านค้าบนแผ่นดิน และตั้งแต่นั้นมา สงครามทุ่นระเบิดก็เริ่มขึ้นในหมู่ผู้ฝึกสอน",
		fmt_en = "#C0x08ED1F#The Pokémons found a land rich in ore. It's said that ores can be exchanged for rich rewards in a shop on the land, and since then Mine War has begun among the trainers."
	},
	[31002] = {
		id = 31002,
		fmt = "#C0xFFF5D6#1. Global Mine War period:#C0x08ED1F#10:00 Saturday-22:00 the following Monday",
		fmt_th = "#C0xFFF5D6#1. Global Mine War ระยะเวลา:#C0x08ED1F#10:00 วันเสาร์-22:00 ของวันจันทร์ถัดไป",
		fmt_en = "#C0xFFF5D6#1. Global Mine War period:#C0x08ED1F#10:00 Saturday-22:00 the following Monday"
	},
	[31003] = {
		id = 31003,
		fmt = "#C0xFFF5D6#2. Daily looting period: #C0x08ED1F#10:00-22:00",
		fmt_th = "#C0xFFF5D6#2. ช่วงเวลาการปล้นประจำวัน: #C0x08ED1F#10:00-22:00",
		fmt_en = "#C0xFFF5D6#2. Daily looting period: #C0x08ED1F#10:00-22:00"
	},
	[31004] = {
		id = 31004,
		fmt = "#C0xFFF5D6#3. Free to grab for #C0x08ED1F#3 times daily",
		fmt_th = "#C0xFFF5D6#3. รับฟรี #C0x08ED1F#3 ครั้งต่อวัน",
		fmt_en = "#C0xFFF5D6#3. Free to grab for #C0x08ED1F#3 times daily"
	},
	[31005] = {
		id = 31005,
		fmt = "#C0xFFF5D6#4. The tournament of each season will match trainers based on their strength and number of participants across several severs. At the end of the match, the servers will be ranked according to the total points achieved by the trainers. The higher the total number of points, the higher the ranking of the server.",
		fmt_th = "#C0xFFF5D6#4. การแข่งขันในแต่ละฤดูกาลจะจับคู่ผู้ฝึกสอนตามความแข็งแกร่งและจำนวนผู้เข้าร่วมในหลาย ๆ เซิร์ฟเวอร์ เมื่อสิ้นสุดการแข่งขัน เซิร์ฟเวอร์จะถูกจัดอันดับตามคะแนนรวมที่ผู้ฝึกทำได้ ยิ่งจำนวนคะแนนรวมมากเท่าไร อันดับของเซิร์ฟเวอร์ก็จะยิ่งสูงขึ้น",
		fmt_en = "#C0xFFF5D6#4. The tournament of each season will match trainers based on their strength and number of participants across several severs. At the end of the match, the servers will be ranked according to the total points achieved by the trainers. The higher the total number of points, the higher the ranking of the server."
	},
	[31006] = {
		id = 31006,
		fmt = "#C0xFFF5D6#5. Trainers can aim to get the final individual reward in the Global Mine War, which is determined by the server ranking and the total of points earned. The final individual reward = basic reward that corresponds to the server ranking + the bonus ratio reward. Therefore, the higher the server ranking and points earned, the better the final individual reward.",
		fmt_th = "#C0xFFF5D6#5. ผู้ฝึกสอนสามารถตั้งเป้าเพื่อรับรางวัลส่วนบุคคลขั้นสุดท้ายในสงครามทุ่นระเบิดโลก ซึ่งกำหนดโดยอันดับเซิร์ฟเวอร์และคะแนนทั้งหมดที่ได้รับ รางวัลบุคคลสุดท้าย = รางวัลพื้นฐานที่สอดคล้องกับอันดับเซิร์ฟเวอร์ + รางวัลอัตราส่วนโบนัส ดังนั้น ยิ่งอันดับเซิร์ฟเวอร์และคะแนนได้รับมากเท่าไร รางวัลสำหรับบุคคลสุดท้ายก็จะยิ่งดีขึ้นเท่านั้น",
		fmt_en = "#C0xFFF5D6#5. Trainers can aim to get the final individual reward in the Global Mine War, which is determined by the server ranking and the total of points earned. The final individual reward = basic reward that corresponds to the server ranking + the bonus ratio reward. Therefore, the higher the server ranking and points earned, the better the final individual reward."
	},
	[31007] = {
		id = 31007,
		fmt = "#C0xFFF5D6#6. Each mine corresponds to a ranking. The higher the ranking, the higher the points. Trainers can challenge the higher ranked players through the nearby mines to improve the ranking, or can proceed to the advanced mining area directly and challenge the top 10 mines",
		fmt_th = "#C0xFFF5D6#6. เหมืองแต่ละอันสอดคล้องกับการจัดอันดับ ยิ่งอันดับสูง คะแนนยิ่งสูง ผู้ฝึกสอนสามารถท้าทายผู้เล่นที่มีอันดับสูงกว่าผ่านเหมืองใกล้เคียงเพื่อปรับปรุงอันดับ หรือสามารถไปยังพื้นที่การทำเหมืองขั้นสูงได้โดยตรงและท้าทายเหมือง 10 อันดับแรก",
		fmt_en = "#C0xFFF5D6#6. Each mine corresponds to a ranking. The higher the ranking, the higher the points. Trainers can challenge the higher ranked players through the nearby mines to improve the ranking, or can proceed to the advanced mining area directly and challenge the top 10 mines"
	},
	[32001] = {
		id = 32001,
		fmt = "#C0xFFF5D6#1. Ore resources can be used to encourage Gottsumon and exchange for items in the Mine War shop",
		fmt_th = "#C0xFFF5D6#1. ทรัพยากรแร่สามารถใช้เพื่อส่งเสริม Gottsumon และแลกเปลี่ยนไอเทมในร้านค้า Mine War",
		fmt_en = "#C0xFFF5D6#1. Ore resources can be used to encourage Gottsumon and exchange for items in the Mine War shop"
	},
	[32002] = {
		id = 32002,
		fmt = "#C0xFFF5D6#2. Buff bonuses can be given to individuals or all trainers in the server by encouraging Gottsumon.",
		fmt_th = "#C0xFFF5D6#2. สามารถมอบโบนัสบัฟให้กับบุคคลหรือผู้ฝึกสอนทุกคนในเซิร์ฟเวอร์ได้โดยการสนับสนุน Gottsumon",
		fmt_en = "#C0xFFF5D6#2. Buff bonuses can be given to individuals or all trainers in the server by encouraging Gottsumon."
	},
	[32003] = {
		id = 32003,
		fmt = "#C0xFFF5D6#3. Mines can produce ores, where the amount of ore produced is tabulated once every 10 minutes. The higher the ranking, the faster the production speed.",
		fmt_th = "#C0xFFF5D6#3. เหมืองสามารถผลิตแร่ได้ โดยจะมีการกำหนดปริมาณแร่ที่ผลิตได้ทุกๆ 10 นาที ยิ่งอันดับสูง ความเร็วในการผลิตก็จะยิ่งเร็วขึ้น",
		fmt_en = "#C0xFFF5D6#3. Mines can produce ores, where the amount of ore produced is tabulated once every 10 minutes. The higher the ranking, the faster the production speed."
	},
	[32004] = {
		id = 32004,
		fmt = "#C0xFFF5D6#4. Trainers can loot other trainers' mines",
		fmt_th = "#C0xFFF5D6#4. ผู้ฝึกสอนสามารถปล้นทุ่นระเบิดของผู้ฝึกสอนคนอื่นได้",
		fmt_en = "#C0xFFF5D6#4. Trainers can loot other trainers' mines"
	},
	[32005] = {
		id = 32005,
		fmt = "#C0xFFF5D6#5. Ores will not be given when you loot players of the same server or players with combat power much lower than yours",
		fmt_th = "#C0xFFF5D6#5. คุณจะไม่ได้รับแร่เมื่อคุณปล้นผู้เล่นจากเซิร์ฟเวอร์เดียวกันหรือผู้เล่นที่มีพลังต่อสู้ต่ำกว่าคุณมาก",
		fmt_en = "#C0xFFF5D6#5. Ores will not be given when you loot players of the same server or players with combat power much lower than yours"
	},
	[32006] = {
		id = 32006,
		fmt = "#C0xFFF5D6#6. There is a maximum number of loot chances, and the number of loots cannot be more than the maximum loot chances given.",
		fmt_th = "#C0xFFF5D6#6. มีโอกาสปล้นได้สูงสุดจำนวน และจำนวนการปล้นต้องไม่เกินโอกาสปล้นสูงสุดที่กำหนด",
		fmt_en = "#C0xFFF5D6#6. There is a maximum number of loot chances, and the number of loots cannot be more than the maximum loot chances given."
	},
	[32007] = {
		id = 32007,
		fmt = "#C0xFFF5D6#7. What a fierce competition in the Global Mine War. During the looting process, as there may be changes to the target trainer's mine, the resources that are looted may eventually be lesser what is seen on the interface. Anyway, fastest fingers first!",
		fmt_th = "#C0xFFF5D6#7. เป็นการแข่งขันที่ดุเดือดใน Global Mine War ในระหว่างกระบวนการปล้นทรัพย์สิน เนื่องจากอาจมีการเปลี่ยนแปลงในเหมืองของผู้ฝึกสอนเป้าหมาย ทรัพยากรที่ถูกปล้นไปในที่สุดอาจน้อยกว่าที่เห็นในอินเทอร์เฟซ ยังไงก็ตาม เร็วสุดก่อน!",
		fmt_en = "#C0xFFF5D6#7. What a fierce competition in the Global Mine War. During the looting process, as there may be changes to the target trainer's mine, the resources that are looted may eventually be lesser what is seen on the interface. Anyway, fastest fingers first!"
	},
	[33001] = {
		id = 33001,
		fmt = "#C0xFFF5D6#1. Trainers can send 3 groups Pokémons to battle, each groups can up to 4 Pokémons",
		fmt_th = "#C0xFFF5D6#1. ผู้ฝึกสามารถส่งโปเกมอนได้ 3 กลุ่มไปต่อสู้ โดยแต่ละกลุ่มส่งโปเกมอนได้มากถึง 4 ตัว",
		fmt_en = "#C0xFFF5D6#1. Trainers can send 3 groups Pokémons to battle, each groups can up to 4 Pokémons"
	},
	[33002] = {
		id = 33002,
		fmt = "#C0xFFF5D6#2. The battle is conducted in a best of 3 format",
		fmt_th = "#C0xFFF5D6#2. การต่อสู้จะดำเนินการใน 3 รูปแบบที่ดีที่สุด",
