	[39005] = {
		id = 39005,
		fmt = "5. Players are free to adjust the line-up until one minute before the tournament starts",
		fmt_th = "5. ผู้เล่นมีอิสระในการปรับรายชื่อจนถึงหนึ่งนาทีก่อนการแข่งขันจะเริ่ม",
		fmt_en = "5. Players are free to adjust the line-up until one minute before the tournament starts"
	},
	[39006] = {
		id = 39006,
		fmt = "6. Trainers of VIP 3 and above register automatically everyday",
		fmt_th = "6. เทรนเนอร์  VIP 3 ขึ้นไป ลงทะเบียนอัตโนมัติทุกวัน",
		fmt_en = "6. Trainers of VIP 3 and above register automatically everyday"
	},
	[39007] = {
		id = 39007,
		fmt = "7. During the battle, both sides can fight up to 10 turns. If the winner is still undecided at the end of the 10th turn, the one with the highest percentage of HP remaining wins.",
		fmt_th = "7. ระหว่างการต่อสู้ ทั้งสองฝ่ายสามารถต่อสู้ได้ถึง 10 เทิร์น หากผู้ชนะยังไม่ตัดสินใจเมื่อจบเทิร์นที่ 10 ผู้ที่มีเปอร์เซ็นต์ HP สูงสุดที่เหลืออยู่จะเป็นผู้ชนะ",
		fmt_en = "7. During the battle, both sides can fight up to 10 turns. If the winner is still undecided at the end of the 10th turn, the one with the highest percentage of HP remaining wins."
	},
	[39008] = {
		id = 39008,
		fmt = "8. There's a point ranking system in the tournament. The points are determined by the damage inflicted by the Pokémon. The higher the damage, the higher the points earned.",
		fmt_th = "8. มีระบบการจัดอันดับคะแนนในการแข่งขัน คะแนนจะถูกกำหนดโดยความเสียหายที่เกิดจากโปเกมอน ยิ่งมีความเสียหายมากเท่าใด คะแนนก็จะยิ่งสูงขึ้นเท่านั้น",
		fmt_en = "8. There's a point ranking system in the tournament. The points are determined by the damage inflicted by the Pokémon. The higher the damage, the higher the points earned."
	},
	[39009] = {
		id = 39009,
		fmt = "9. Trainers can start placing their bets at 10:00 daily. The higher the odds, the better the rewards of up to 10,000,000 coins per day.",
		fmt_th = "9. ผู้ฝึกสอนสามารถเริ่มวางเดิมพันได้ในเวลา 10.00 น. ทุกวัน ยิ่งโอกาสสูง รางวัลยิ่งดีถึง 10,000,000 เหรียญต่อวัน",
		fmt_en = "9. Trainers can start placing their bets at 10:00 daily. The higher the odds, the better the rewards of up to 10,000,000 coins per day."
	},
	[39010] = {
		id = 39010,
		fmt = "10.  If the contester you bet on enters the quarterfinals but does not win the championship, a partial amount of the bet will be returned. But if the contester does not enter the quarterfinals, you will not receive any amount of your bet.",
		fmt_th = "10. หากผู้แข่งขันที่คุณเดิมพันเข้าสู่รอบก่อนรองชนะเลิศแต่ไม่ชนะการแข่งขัน เงินเดิมพันบางส่วนจะถูกส่งคืน แต่ถ้าผู้แข่งขันไม่เข้าสู่รอบก่อนรองชนะเลิศ คุณจะไม่ได้รับเงินเดิมพันใดๆ",
		fmt_en = "10.  If the contester you bet on enters the quarterfinals but does not win the championship, a partial amount of the bet will be returned. But if the contester does not enter the quarterfinals, you will not receive any amount of your bet."
	},
	[40001] = {
		id = 40001,
		fmt = "1. The qualifier adopts a knockout system. There will be a total of 10 matches, each game lasting 4 minutes. The ranking is based on the number of victories and the victory is also ranked according to the points earned.",
		fmt_th = "1. รอบคัดเลือกใช้ระบบน็อคเอาท์ จะมีทั้งหมด 10 แมตช์ แต่ละเกมใช้เวลา 4 นาที การจัดอันดับขึ้นอยู่กับจำนวนชัยชนะและชัยชนะยังได้รับการจัดอันดับตามคะแนนที่ได้รับ",
		fmt_en = "1. The qualifier adopts a knockout system. There will be a total of 10 matches, each game lasting 4 minutes. The ranking is based on the number of victories and the victory is also ranked according to the points earned."
	},
	[40002] = {
		id = 40002,
		fmt = "2. One Pokémon will fight in each match",
		fmt_th = "2. โปเกมอนหนึ่งตัวจะต่อสู้ในแต่ละแมตช์",
		fmt_en = "2. One Pokémon will fight in each match"
	},
	[40003] = {
		id = 40003,
		fmt = "3. Trainers are eliminated immediately when they accumulate a total of #C0xF76B45# 3 losses",
		fmt_th = "3. ผู้ฝึกสอนจะถูกกำจัดทันทีเมื่อสะสมรวม #C0xF76B45# 3 ขาดทุน",
		fmt_en = "3. Trainers are eliminated immediately when they accumulate a total of #C0xF76B45# 3 losses"
	},
	[40004] = {
		id = 40004,
		fmt = "4. Trainers can earn points for each match. When the qualifier ends, the top 8 trainers will emerge according to number of victories and the ranking of points.",
		fmt_th = "4. ผู้ฝึกสอนสามารถรับคะแนนสำหรับการแข่งขันแต่ละครั้ง เมื่อรอบคัดเลือกสิ้นสุดลง ผู้ฝึกสอน 8 อันดับแรกจะปรากฎตัวตามจำนวนชัยชนะและอันดับคะแนน",
		fmt_en = "4. Trainers can earn points for each match. When the qualifier ends, the top 8 trainers will emerge according to number of victories and the ranking of points."
	},
	[40005] = {
		id = 40005,
		fmt = "5. Pokémon cannot be used repeatedly",
		fmt_th = "5. โปเกมอนไม่สามารถใช้ซ้ำได้",
		fmt_en = "5. Pokémon cannot be used repeatedly"
	},
	[41001] = {
		id = 41001,
		fmt = "1. The top 8 matches are based on elimination format, including quarterfinals, semifinals, championship, and third place match. The duration of each match is 5 minutes.",
		fmt_th = "1. การแข่งขัน 8 อันดับแรกจะพิจารณาจากรูปแบบการคัดออก ได้แก่ รอบก่อนรองชนะเลิศ, รอบรองชนะเลิศ, แชมเปี้ยนชิพ และนัดชิงอันดับสาม ระยะเวลาของแต่ละแมตช์คือ 5 นาที",
		fmt_en = "1. The top 8 matches are based on elimination format, including quarterfinals, semifinals, championship, and third place match. The duration of each match is 5 minutes."
	},
	[41002] = {
		id = 41002,
		fmt = "2. Trainers have to send 3 Pokémons in every match and battle in sequence. The tournament is conducted in tag match format",
		fmt_th = "2. ผู้ฝึกสอนต้องส่งโปเกมอน 3 ตัวในทุกแมตช์และต่อสู้ตามลำดับ การแข่งขันจะดำเนินการในรูปแบบแท็กแมตช์",
		fmt_en = "2. Trainers have to send 3 Pokémons in every match and battle in sequence. The tournament is conducted in tag match format"
	},
	[41003] = {
		id = 41003,
		fmt = "3. You lose when all 3 Pokémons are defeated",
		fmt_th = "3. คุณจะแพ้เมื่อโปเกมอน 3 ตัวถูกกำจัด",
		fmt_en = "3. You lose when all 3 Pokémons are defeated"
	},
	[41004] = {
		id = 41004,
		fmt = "4. Pokémon cannot be used repeatedly",
		fmt_th = "4. โปเกมอนไม่สามารถใช้ซ้ำได้",
		fmt_en = "4. Pokémon cannot be used repeatedly"
	},
	[42001] = {
		id = 42001,
		fmt = "1. Trainers get a treasure chest as a reward for entering each match",
		fmt_th = "1. เทรนเนอร์จะได้รับหีบสมบัติเป็นรางวัลเมื่อเข้าแต่ละแมตช์",
		fmt_en = "1. Trainers get a treasure chest as a reward for entering each match"
	},
	[42002] = {
		id = 42002,
		fmt = "2. You get gold chest for every victory, silver chest for every defeat",
		fmt_th = "2. คุณได้รับหีบทองคำสำหรับทุกชัยชนะ หีบเงินสำหรับทุกความพ่ายแพ้",
		fmt_en = "2. You get gold chest for every victory, silver chest for every defeat"
	},
	[42003] = {
		id = 42003,
		fmt = "3. There are chances of getting Indigo Plateau souvenirs and other items from opening both chests.",
		fmt_th = "3.มีโอกาสได้รับของที่ระลึกที่ราบสูงอินดิโกและของอื่นๆ จากการเปิดหีบทั้งสอง",
		fmt_en = "3. There are chances of getting Indigo Plateau souvenirs and other items from opening both chests."
	},
	[42004] = {
		id = 42004,
		fmt = "4. Ranking rewards are given according to the trainer's ranking in the Indigo Plateau Conference.",
		fmt_th = "4. รางวัลการจัดอันดับจะมอบให้ตามอันดับของผู้ฝึกสอนในการประชุมที่ราบสูงอินดิโก",
		fmt_en = "4. Ranking rewards are given according to the trainer's ranking in the Indigo Plateau Conference."
	},
	[43001] = {
		id = 43001,
		fmt = "#C0xFFF5D6#1. You can play 5 times a day at the beginning. Upgrade 'Agnimon Draw' technology level in the Research Institute to increase the number of playing times",
		fmt_th = "#C0xFFF5D6#1. คุณสามารถเล่นได้ 5 ครั้งต่อวันในตอนเริ่มต้น อัพเกรดระดับเทคโนโลยี 'Agnimon Draw' ในสถาบันวิจัยเพื่อเพิ่มจำนวนครั้งในการเล่น",
		fmt_en = "#C0xFFF5D6#1. You can play 5 times a day at the beginning. Upgrade 'Agnimon Draw' technology level in the Research Institute to increase the number of playing times"
	},
	[43002] = {
		id = 43002,
		fmt = "#C0xFFF5D6#2. In the beginning of this mode, trainers can change their draws 5 times for free. Upgrading related technologies in the research institute can increase the number of free changes as well",
		fmt_th = "#C0xFFF5D6#2. ในช่วงเริ่มต้นของโหมดนี้ ผู้ฝึกสอนสามารถเปลี่ยนการจับฉลากได้ฟรี 5 ครั้ง การอัพเกรดเทคโนโลยีที่เกี่ยวข้องในสถาบันวิจัยสามารถเพิ่มจำนวนการเปลี่ยนแปลงฟรีได้เช่นกัน",
		fmt_en = "#C0xFFF5D6#2. In the beginning of this mode, trainers can change their draws 5 times for free. Upgrading related technologies in the research institute can increase the number of free changes as well"
	},
	[43003] = {
		id = 43003,
		fmt = "#C0xFFF5D6#3. The Agnimons drawn will not disappear. 4. The more Agnimons you get, the more rewards you receive, including Agnimon shards and plenty of Guild Coins",
		fmt_th = "#C0xFFF5D6#3. Agnimons ที่วาดจะไม่หายไป 4. ยิ่งคุณได้รับ Agnimons มากเท่าใด คุณก็ยิ่งได้รับรางวัลมากเท่านั้น รวมถึงชิ้นส่วน Agnimon และกิลด์มากมาย  Coins",
		fmt_en = "#C0xFFF5D6#3. The Agnimons drawn will not disappear. 4. The more Agnimons you get, the more rewards you receive, including Agnimon shards and plenty of Guild Coins"
	},
	[43004] = {
		id = 43004,
		fmt = "#C0xFFF5D6#4.The higher the number of Agnimon, the better the rewards. You can get a huge amount of Agnimon shard and Guild Coins.",
		fmt_th = "#C0xFFF5D6#4 ยิ่งจำนวน Agnimon สูง รางวัลก็ยิ่งดี คุณสามารถรับชิ้นส่วน Agnimon และ Guild  Coins ได้เป็นจำนวนมาก",
		fmt_en = "#C0xFFF5D6#4.The higher the number of Agnimon, the better the rewards. You can get a huge amount of Agnimon shard and Guild Coins."
	},
	[44001] = {
		id = 44001,
		fmt = "1. Union Dungeon opening hours: Monday to Saturday 9:30-23:00, closes on Sunday;",
		fmt_th = "1. เวลาทำการ Union Dungeon: วันจันทร์ถึงวันเสาร์ 9:30-23:00 น. ปิดวันอาทิตย์",
		fmt_en = "1. Union Dungeon opening hours: Monday to Saturday 9:30-23:00, closes on Sunday;"
	},
	[44002] = {
		id = 44002,
		fmt = "2. The system resets the dungeons automatically at every Monday, Wednesday and Friday at 05:00. Only the dungeon with the highest difficult currently will be reset;",
		fmt_th = "2. ระบบจะรีเซ็ตดันเจี้ยนอัตโนมัติทุกวันจันทร์ พุธ และศุกร์ เวลา 05:00 น. เฉพาะดันเจี้ยนที่มีความยากสูงสุดในปัจจุบันเท่านั้นที่จะถูกรีเซ็ต",
		fmt_en = "2. The system resets the dungeons automatically at every Monday, Wednesday and Friday at 05:00. Only the dungeon with the highest difficult currently will be reset;"
	},
	[44003] = {
		id = 44003,
		fmt = "3. There are 3 chances to challenge any of the dungeons each day, and will be reset at 05:00 every day. There will be chances of getting union Boss Chests during the challenge;",
		fmt_th = "3. มีโอกาส 3 ครั้งที่จะท้าทายดันเจี้ยนในแต่ละวัน และจะถูกรีเซ็ตเวลา 05:00 น. ทุกวัน จะมีโอกาสได้รับหีบบอสของสหภาพระหว่างการท้าทาย",
		fmt_en = "3. There are 3 chances to challenge any of the dungeons each day, and will be reset at 05:00 every day. There will be chances of getting union Boss Chests during the challenge;"
	},
	[44004] = {
		id = 44004,
		fmt = "4. Another dungeon will unlock when the current one is cleared, and the cleared dungeon cannot be challenged again until it is reset every monthly;",
		fmt_th = "4. ดันเจี้ยนอื่นจะปลดล็อกเมื่อดันเจี้ยนปัจจุบันถูกเคลียร์ และดันเจี้ยนที่เคลียร์แล้วจะไม่สามารถท้าทายได้อีกจนกว่าจะรีเซ็ตทุกเดือน",
		fmt_en = "4. Another dungeon will unlock when the current one is cleared, and the cleared dungeon cannot be challenged again until it is reset every monthly;"
	},
	[44005] = {
		id = 44005,
		fmt = "5. After completing each Guild Dungeon challenge, additional ranking rewards will be given according to your contribution in the dungeons;",
		fmt_th = "5. หลังจากเสร็จสิ้นการท้าทายดันเจี้ยนกิลด์แต่ละครั้ง รางวัลอันดับเพิ่มเติมจะมอบให้ตามการมีส่วนร่วมของคุณในดันเจี้ยน",
		fmt_en = "5. After completing each Guild Dungeon challenge, additional ranking rewards will be given according to your contribution in the dungeons;"
	},
	[44006] = {
		id = 44006,
		fmt = "6. There's a first time clearance reward for each dungeon, and each trainer can only claim it once;",
		fmt_th = "6. มีรางวัลการกวาดล้างครั้งแรกสำหรับแต่ละดันเจี้ยน และผู้ฝึกสอนแต่ละคนสามารถรับได้เพียงครั้งเดียวเท่านั้น",
		fmt_en = "6. There's a first time clearance reward for each dungeon, and each trainer can only claim it once;"
	},
	[44007] = {
		id = 44007,
		fmt = "7. Union members will receive additional attack, defense, and health bonuses according to the number of times and the duration each Union took to complete the levels. The bonuses will only take effect in the current dungeon;",
		fmt_th = "7. สมาชิกสหภาพจะได้รับโบนัสการโจมตี การป้องกัน และสุขภาพเพิ่มเติมตามจำนวนครั้งและระยะเวลาที่แต่ละสหภาพใช้ในการผ่านด่าน โบนัสจะมีผลเฉพาะในดันเจี้ยนปัจจุบันเท่านั้น",
		fmt_en = "7. Union members will receive additional attack, defense, and health bonuses according to the number of times and the duration each Union took to complete the levels. The bonuses will only take effect in the current dungeon;"
	},
	[44008] = {
		id = 44008,
		fmt = "8. All dungeons are reset at the beginning of the month, and all unions can claim killing rewards after clearing one dungeon after the reset (non-first time clearance reward);",
		fmt_th = "8. ดันเจี้ยนทั้งหมดจะถูกรีเซ็ตเมื่อต้นเดือน และสหภาพทั้งหมดสามารถรับรางวัลการฆ่าได้หลังจากเคลียร์ดันเจี้ยนหนึ่งหลังหลังจากรีเซ็ตแล้ว (รางวัลการเคลียร์ที่ไม่ใช่ครั้งแรก)",
		fmt_en = "8. All dungeons are reset at the beginning of the month, and all unions can claim killing rewards after clearing one dungeon after the reset (non-first time clearance reward);"
	},
	[44009] = {
		id = 44009,
		fmt = "9. Kill rewards (for non-first time level clearance) - each trainer can only claim once in each dungeon for each reset;",
		fmt_th = "9. รางวัลการสังหาร (สำหรับการเคลียร์เลเวลที่ไม่ใช่ครั้งแรก) - ผู้ฝึกสอนแต่ละคนสามารถรับสิทธิ์ได้เพียงครั้งเดียวในแต่ละดันเจี้ยนสำหรับการรีเซ็ตแต่ละครั้ง",
		fmt_en = "9. Kill rewards (for non-first time level clearance) - each trainer can only claim once in each dungeon for each reset;"
	},
	[44010] = {
		id = 44010,
		fmt = "10. After changing union, trainers cannot challenge the union dungeon until 05:00 the next day",
		fmt_th = "10. หลังจากเปลี่ยนสหภาพแล้ว ผู้ฝึกสอนจะไม่สามารถท้าทายดันเจี้ยนสหภาพได้จนถึงเวลา 05:00 น. ของวันถัดไป",
		fmt_en = "10. After changing union, trainers cannot challenge the union dungeon until 05:00 the next day"
	},
	[44011] = {
		id = 44011,
		fmt = "11. For each trainer to last-hit the Guild BOSS can get additional coin and diamond reward. Kill reward of the same BOSS can only obtain once in one-month reset period",
		fmt_th = "11. สำหรับผู้ฝึกสอนแต่ละคนที่กด  Guild BOSS ครั้งสุดท้ายจะได้รับเหรียญและเพชรเพิ่มเติม รางวัลการสังหารของบอสตัวเดียวกันสามารถรับได้เพียงครั้งเดียวในช่วงเวลารีเซ็ตหนึ่งเดือน",
		fmt_en = "11. For each trainer to last-hit the Guild BOSS can get additional coin and diamond reward. Kill reward of the same BOSS can only obtain once in one-month reset period"
	},
	[44012] = {
		id = 44012,
		fmt = "12. All kill rewards need to be manually collected in the reward box。 Participation rewards and last hit rewards will be issued when challenge is settled. Damage ranking rewards will be issued by mail.",
		fmt_th = "12. รางวัลการฆ่าทั้งหมดจะต้องรวบรวมด้วยตนเองในกล่องรางวัล。 รางวัลการเข้าร่วมและรางวัลการโจมตีครั้งสุดท้ายจะออกเมื่อการท้าทายถูกตัดสิน รางวัลอันดับความเสียหายจะออกทางไปรษณีย์",
		fmt_en = "12. All kill rewards need to be manually collected in the reward box。 Participation rewards and last hit rewards will be issued when challenge is settled. Damage ranking rewards will be issued by mail."
	},
	[45001] = {
		id = 45001,
		fmt = "1. Each member can make one wish daily by posting the Pokémon shard of their wish within the guild",
		fmt_th = "1. สมาชิกแต่ละคนสามารถขอพรได้ 1 อย่างทุกวันโดยโพสต์ชิ้นส่วนโปเกมอนที่ต้องการภายในกิลด์",
		fmt_en = "1. Each member can make one wish daily by posting the Pokémon shard of their wish within the guild"
	},
	[45002] = {
		id = 45002,
		fmt = "2. You can also wish for Pokémons that you already own",
		fmt_th = "2. คุณสามารถขอโปเกมอนที่คุณมีอยู่แล้วได้",
		fmt_en = "2. You can also wish for Pokémons that you already own"
	},
	[45003] = {
		id = 45003,
		fmt = "3. For Pokémons of different qualities, the maximum number of resources that can be obtained for each wish is different. The higher the quality of the Pokémon, the less the number of resources can be obtained",
		fmt_th = "3. สำหรับโปเกมอนที่มีคุณภาพต่างกัน จำนวนทรัพยากรสูงสุดที่สามารถรับได้สำหรับแต่ละความปรารถนาจะแตกต่างกัน ยิ่งคุณภาพของโปเกมอนสูงเท่าไหร่ ก็ยิ่งได้รับทรัพยากรน้อยลงเท่านั้น",
		fmt_en = "3. For Pokémons of different qualities, the maximum number of resources that can be obtained for each wish is different. The higher the quality of the Pokémon, the less the number of resources can be obtained"
	},
	[45004] = {
		id = 45004,
		fmt = "4. You can give other members the shards you own to fulfill their wishes. You can only give 1 shard to the same member,",
		fmt_th = "4. คุณสามารถมอบส่วนแบ่งที่คุณมีให้กับสมาชิกคนอื่น ๆ เพื่อเติมเต็มความปรารถนาของพวกเขา คุณสามารถให้ 1 ชาร์ดแก่สมาชิกคนเดียวกันเท่านั้น",
		fmt_en = "4. You can give other members the shards you own to fulfill their wishes. You can only give 1 shard to the same member,"
	},
	[45005] = {
		id = 45005,
		fmt = "5. The gifted shard will be sent to the receiving member via mail",
		fmt_th = "5. ชิ้นส่วนที่มีพรสวรรค์จะถูกส่งไปยังสมาชิกที่ได้รับทางไปรษณีย์",
		fmt_en = "5. The gifted shard will be sent to the receiving member via mail"
	},
	[45006] = {
		id = 45006,
		fmt = "6. Gift Pokémon shards of different  quality to get different amounts of Pokémon soul stones and Helpful Points rewards",
		fmt_th = "6. มอบชิ้นส่วนโปเกมอนที่มีคุณภาพแตกต่างกันเพื่อรับหินวิญญาณโปเกมอนและคะแนนช่วยเหลือที่แตกต่างกัน",
		fmt_en = "6. Gift Pokémon shards of different  quality to get different amounts of Pokémon soul stones and Helpful Points rewards"
	},
	[45007] = {
		id = 45007,
		fmt = "7. All wishes will be removed at 05:00 daily",
		fmt_th = "7. คำอธิษฐานทั้งหมดจะถูกลบออกเวลา 05:00 น. ทุกวัน",
		fmt_en = "7. All wishes will be removed at 05:00 daily"
	},
	[46001] = {
		id = 46001,
		fmt = "#C0xFFF5D6#1. Trainers get a treasure chest as a reward for entering each match",
		fmt_th = "#C0xFFF5D6#1. ผู้ฝึกสอนจะได้รับหีบสมบัติเป็นรางวัลสำหรับการเข้าแข่งขันแต่ละครั้ง",
		fmt_en = "#C0xFFF5D6#1. Trainers get a treasure chest as a reward for entering each match"
	},
	[46002] = {
		id = 46002,
		fmt = "#C0xFFF5D6#2. You get gold chest for every victory, silver chest for every defeat",
		fmt_th = "#C0xFFF5D6#2. คุณจะได้รับหีบทองสำหรับทุกชัยชนะ หีบเงินสำหรับทุกความพ่ายแพ้",
		fmt_en = "#C0xFFF5D6#2. You get gold chest for every victory, silver chest for every defeat"
	},
	[46003] = {
		id = 46003,
		fmt = "#C0xFFF5D6#3. There will be a chance to get rings, badges, and other items from the two types of chests.",
		fmt_th = "#C0xFFF5D6#3. จะมีโอกาสได้รับแหวน ตราสัญลักษณ์ และไอเทมอื่นๆ จากหีบทั้งสองประเภท",
		fmt_en = "#C0xFFF5D6#3. There will be a chance to get rings, badges, and other items from the two types of chests."
	},
	[46004] = {
		id = 46004,
		fmt = "#C0xFFF5D6#4. Rank rewards are given based on day's ranking of Battle of the King, including rare items such as Angemon shards",
		fmt_th = "#C0xFFF5D6#4. รางวัลอันดับจะมอบให้ตามอันดับของ Battle of the King ในแต่ละวัน รวมถึงไอเทมหายาก เช่น ชาร์ด Angemon",
		fmt_en = "#C0xFFF5D6#4. Rank rewards are given based on day's ranking of Battle of the King, including rare items such as Angemon shards"
	},
	[47001] = {
		id = 47001,
		fmt = "1. Insert the metal into the Pokémon's matrix slot to give the Pokémon metal value bonus. The matrix slots unlock as the team level increases;",
		fmt_th = "1. ใส่โลหะลงในช่องเมทริกซ์ของโปเกมอนเพื่อให้โบนัสมูลค่าโลหะโปเกมอน สล็อตเมทริกซ์จะปลดล็อกเมื่อระดับทีมเพิ่มขึ้น",
		fmt_en = "1. Insert the metal into the Pokémon's matrix slot to give the Pokémon metal value bonus. The matrix slots unlock as the team level increases;"
	},
	[47002] = {
		id = 47002,
		fmt = "2. When the specific type of metal is placed in the matrix slot, the matrix stats bonus can be activated, and the Pokémon's strength will further be enhanced;",
		fmt_th = "2. เมื่อวางประเภทโลหะเฉพาะลงในช่องเมทริกซ์ โบนัสสถิติเมทริกซ์สามารถเปิดใช้งานได้ และความแรงของโปเกมอนจะเพิ่มขึ้นอีก",
		fmt_en = "2. When the specific type of metal is placed in the matrix slot, the matrix stats bonus can be activated, and the Pokémon's strength will further be enhanced;"
	},
	[47003] = {
		id = 47003,
		fmt = "3. The matrix effect itself has a variety of grades. When the metals that activate the matrix effect reaches a certain grade, the matrix effect can also be upgraded to that grade. This means that the strength of the matrix effect depends on the lowest grade of metal in the matrix;",
		fmt_th = "3. เอฟเฟกต์เมทริกซ์นั้นมีหลายเกรด เมื่อโลหะที่เปิดใช้งานเอฟเฟกต์เมทริกซ์ถึงระดับหนึ่ง เอฟเฟกต์เมทริกซ์สามารถอัพเกรดเป็นเกรดนั้นได้ ซึ่งหมายความว่าความแข็งแรงของเอฟเฟกต์เมทริกซ์ขึ้นอยู่กับเกรดโลหะที่ต่ำที่สุดในเมทริกซ์",
		fmt_en = "3. The matrix effect itself has a variety of grades. When the metals that activate the matrix effect reaches a certain grade, the matrix effect can also be upgraded to that grade. This means that the strength of the matrix effect depends on the lowest grade of metal in the matrix;"
	},
	[47004] = {
		id = 47004,
		fmt = "4. When a Pokémon activates a matrix effect and there are still empty slots in the matrix, trainers can choose the metal of your choice in the empty slot without affecting the activation of matrix effect;",
		fmt_th = "4. เมื่อโปเกมอนเปิดใช้งานเอฟเฟกต์เมทริกซ์และยังมีช่องว่างในเมทริกซ์ ผู้ฝึกสอนสามารถเลือกโลหะที่คุณต้องการในช่องว่างโดยไม่ส่งผลต่อการเปิดใช้งานเอฟเฟกต์เมทริกซ์",
		fmt_en = "4. When a Pokémon activates a matrix effect and there are still empty slots in the matrix, trainers can choose the metal of your choice in the empty slot without affecting the activation of matrix effect;"
	},
	[47005] = {
		id = 47005,
		fmt = "5. Excess metals can be converted into metal essence through metal smelting, and the metal essence can be used to upgrade the level of other metals.",
		fmt_th = "5. โลหะส่วนเกินสามารถเปลี่ยนเป็นสาระสำคัญของโลหะผ่านการถลุงโลหะ และสาระสำคัญของโลหะสามารถใช้ในการอัพเกรดระดับของโลหะอื่น ๆ",
		fmt_en = "5. Excess metals can be converted into metal essence through metal smelting, and the metal essence can be used to upgrade the level of other metals."
	},
	[48001] = {
		id = 48001,
		fmt = "Complete the daily tasks in the list to earn and collect the corresponding activity points.",
		fmt_th = "ทำงานประจำวันให้เสร็จในรายการเพื่อรับและรวบรวมคะแนนกิจกรรมที่เกี่ยวข้อง",
		fmt_en = "Complete the daily tasks in the list to earn and collect the corresponding activity points."
	},
	[48002] = {
		id = 48002,
		fmt = "When the total daily activity points has reached 20, 40, 60, 80 or 100, trainers can claim rewards from the activity chests.",
		fmt_th = "เมื่อคะแนนกิจกรรมประจำวันทั้งหมดถึง 20, 40, 60, 80 หรือ 100 ผู้ฝึกสามารถรับรางวัลจากหีบกิจกรรมได้",
		fmt_en = "When the total daily activity points has reached 20, 40, 60, 80 or 100, trainers can claim rewards from the activity chests."
	},
	[48003] = {
		id = 48003,
		fmt = "Certain activity quests, such as total online duration and energy usage, can be completed in stages, and each stage will provide activity points of that stage.",
		fmt_th = "เควสกิจกรรมบางอย่าง เช่น ระยะเวลาออนไลน์ทั้งหมดและการใช้พลังงาน สามารถทำได้เป็นด่าน และแต่ละด่านจะมอบคะแนนกิจกรรมของด่านนั้น",
		fmt_en = "Certain activity quests, such as total online duration and energy usage, can be completed in stages, and each stage will provide activity points of that stage."
	},
	[49001] = {
		id = 49001,
		fmt = "1. You get 10 points each time you draw a time-limited chest. The number of points determines your ranking. When the number of points are the same, the player who attains the points first will be ranked higher.",
		fmt_th = "1. คุณจะได้รับ 10 แต้มทุกครั้งที่คุณจั่วกล่องที่จำกัดเวลา จำนวนคะแนนเป็นตัวกำหนดอันดับของคุณ เมื่อแต้มเท่ากัน ผู้เล่นที่ได้แต้มก่อนจะมีอันดับสูงกว่า",
		fmt_en = "1. You get 10 points each time you draw a time-limited chest. The number of points determines your ranking. When the number of points are the same, the player who attains the points first will be ranked higher."
	},
	[49002] = {
		id = 49002,
		fmt = "2. In this event, you will get awakening metals and universal shard chest for every 10 consecutive equipment chest drawn (the awakening shard is excluded)",
		fmt_th = "2. ในกิจกรรมนี้ คุณจะได้รับ Awakening Metal และ Universal Shard Chest จากทุก ๆ 10 หีบอุปกรณ์ที่สุ่มออกมา (ไม่รวม Awakening Shard)",
		fmt_en = "2. In this event, you will get awakening metals and universal shard chest for every 10 consecutive equipment chest drawn (the awakening shard is excluded)"
	},
	[49003] = {
		id = 49003,
		fmt = "3. The event ends at 21:30 on the last day. When it ends, trainers cannot draw prizes anymore and rewards for the top 30 trainers will be given via mail",
		fmt_th = "3. กิจกรรมสิ้นสุดเวลา 21:30 น. ของวันสุดท้าย เมื่อหมดเขตผู้ฝึกสอนจะไม่สามารถจับรางวัลได้อีกต่อไปและจะมอบรางวัลให้กับผู้ฝึกสอน 30 อันดับแรกทางไปรษณีย์",
		fmt_en = "3. The event ends at 21:30 on the last day. When it ends, trainers cannot draw prizes anymore and rewards for the top 30 trainers will be given via mail"
	},
	[49004] = {
		id = 49004,
		fmt = "4. 7000 points are needed to get the Rank 1 reward",
		fmt_th = "4. ต้องใช้ 7000 คะแนนเพื่อรับรางวัลอันดับ 1",
		fmt_en = "4. 7000 points are needed to get the Rank 1 reward"
	},
	[49005] = {
		id = 49005,
		fmt = "5. 2 points is required to get ranking rewards for rank No. 3-5000",
		fmt_th = "5. ต้องใช้ 2 คะแนนเพื่อรับรางวัลการจัดอันดับสำหรับอันดับที่ 3-5000",
		fmt_en = "5. 2 points is required to get ranking rewards for rank No. 3-5000"
	},
	[49006] = {
		id = 49006,
		fmt = "6. 4 points is required to get ranking rewards for rank No. 6-3500",
		fmt_th = "6. ต้องใช้ 4 คะแนนเพื่อรับรางวัลการจัดอันดับสำหรับอันดับที่ 6-3500",
		fmt_en = "6. 4 points is required to get ranking rewards for rank No. 6-3500"
	},
	[49007] = {
		id = 49007,
		fmt = "7. 7 points is required to get ranking rewards for rank No. 10-2000",
		fmt_th = "7. ต้องใช้ 7 คะแนนเพื่อรับรางวัลการจัดอันดับสำหรับอันดับที่ 10-2000",
		fmt_en = "7. 7 points is required to get ranking rewards for rank No. 10-2000"
	},
	[49008] = {
		id = 49008,
		fmt = "8. 11 points is required to get ranking rewards for rank No. 20-1000",
		fmt_th = "8. ต้องใช้ 11 คะแนนเพื่อรับรางวัลการจัดอันดับสำหรับอันดับที่ 20-1000",
		fmt_en = "8. 11 points is required to get ranking rewards for rank No. 20-1000"
	},
	[49009] = {
		id = 49009,
		fmt = "9. If you do not meet the point requirement for the event, you can only receive rewards corresponding to the number of points you earn",
		fmt_th = "9. หากคุณไม่มีคะแนนตามข้อกำหนดสำหรับกิจกรรม คุณจะได้รับรางวัลตามจำนวนคะแนนที่คุณได้รับเท่านั้น",
		fmt_en = "9. If you do not meet the point requirement for the event, you can only receive rewards corresponding to the number of points you earn"
	},
	[50001] = {
		id = 50001,
		fmt = "1. During the event period, for every ￥6 purchased, you get a hammer for cracking the Golden Egg. You can only get up to 10 hammers a day.",
		fmt_th = "1. ในช่วงระยะเวลากิจกรรม ทุกๆ ￥6 ที่ซื้อ คุณจะได้รับค้อนสำหรับทุบไข่ทองคำ คุณสามารถรับได้ถึง 10 ค้อนต่อวันเท่านั้น",
		fmt_en = "1. During the event period, for every ￥6 purchased, you get a hammer for cracking the Golden Egg. You can only get up to 10 hammers a day."
	},
	[50002] = {
		id = 50002,
		fmt = "2. The steps for cracking golden eggs: If you have a hammer, tap on the golden egg of your choice with it to get a reward.",
		fmt_th = "2. ขั้นตอนในการแตกไข่ทองคำ: หากคุณมีค้อน ให้แตะที่ไข่ทองคำที่คุณเลือกเพื่อรับรางวัล",
		fmt_en = "2. The steps for cracking golden eggs: If you have a hammer, tap on the golden egg of your choice with it to get a reward."
	},
	[50003] = {
		id = 50003,
		fmt = "3. 1 hammer and XXXX currency are needed each time you smash a golden egg (read quantity and coins configuration). Each time you smash an egg, you have a chance to get 3x, 6x, and 10x the reward.",
		fmt_th = "3. ต้องใช้ค้อน 1 อันและสกุลเงิน XXXX ทุกครั้งที่คุณทุบไข่ทองคำ (อ่านปริมาณและการกำหนดค่าเหรียญ) ทุกครั้งที่คุณทุบไข่ คุณจะมีโอกาสได้รับรางวัล 3x, 6x และ 10x",
		fmt_en = "3. 1 hammer and XXXX currency are needed each time you smash a golden egg (read quantity and coins configuration). Each time you smash an egg, you have a chance to get 3x, 6x, and 10x the reward."
	},
	[50004] = {
		id = 50004,
		fmt = "4. When you hit 10x Jackpot, it will immediately reset to 3 golden eggs. Otherwise, you can continue to smash the remaining golden eggs until you hit a prize.",
		fmt_th = "4. เมื่อคุณกดแจ็คพอต 10 เท่า มันจะรีเซ็ตเป็นไข่ทองคำ 3 ฟองทันที มิเช่นนั้นคุณสามารถทุบไข่ทองคำที่เหลือต่อไปได้จนกว่าคุณจะได้รับรางวัล",
		fmt_en = "4. When you hit 10x Jackpot, it will immediately reset to 3 golden eggs. Otherwise, you can continue to smash the remaining golden eggs until you hit a prize."
	},
	[50005] = {
		id = 50005,
		fmt = "5. If you're lucky, you will be able to hit the 10x Jackpot on your first try; otherwise, 10x rewards will still be guaranteed on your third try.",
		fmt_th = "5. หากคุณโชคดี คุณจะสามารถได้รับแจ็คพอต 10x ในการลองครั้งแรกของคุณ มิฉะนั้น รางวัล 10x จะยังคงรับประกันในการลองครั้งที่สามของคุณ",
		fmt_en = "5. If you're lucky, you will be able to hit the 10x Jackpot on your first try; otherwise, 10x rewards will still be guaranteed on your third try."
	},
	[51001] = {
		id = 51001,
		fmt = "1. The limited-time Boss event is an event where trainers get three attempts to challenge the Boss daily. The attempts will reset at 05:00 daily. If they are all used up, diamonds can be spent to purchase for more attempts.",
		fmt_th = "1. อีเวนต์บอสแบบจำกัดเวลาคืออีเวนต์ที่ผู้ฝึกสอนพยายามท้าทายบอสสามครั้งทุกวัน ความพยายามจะรีเซ็ตเวลา 05:00 น. ทุกวัน หากใช้จนหมด สามารถใช้เพชรเพื่อซื้อเพิ่มได้",
		fmt_en = "1. The limited-time Boss event is an event where trainers get three attempts to challenge the Boss daily. The attempts will reset at 05:00 daily. If they are all used up, diamonds can be spent to purchase for more attempts."
	},
	[51002] = {
		id = 51002,
		fmt = "2. The ranking will record the trainer's highest single damage dealt and not the total damage dealt;",
		fmt_th = "2. การจัดอันดับจะบันทึกความเสียหายเดี่ยวสูงสุดของผู้ฝึกสอน ไม่ใช่ความเสียหายทั้งหมดที่ทำ",
		fmt_en = "2. The ranking will record the trainer's highest single damage dealt and not the total damage dealt;"
	},
	[51003] = {
		id = 51003,
		fmt = "3. Each challenge will give a certain amount of coins and item rewards;",
		fmt_th = "3. การท้าทายแต่ละครั้งจะให้เหรียญและรางวัลไอเท็มจำนวนหนึ่ง",
		fmt_en = "3. Each challenge will give a certain amount of coins and item rewards;"
	},
	[51004] = {
		id = 51004,
		fmt = "4. During event period, the leaderboard will reset every day at 05:00, and ranking rewards will be given according to the damage ranking;",
		fmt_th = "4. ในช่วงระยะเวลากิจกรรม กระดานผู้นำจะรีเซ็ตทุกวันเวลา 05:00 น. และรางวัลอันดับจะมอบให้ตามอันดับความเสียหาย",
		fmt_en = "4. During event period, the leaderboard will reset every day at 05:00, and ranking rewards will be given according to the damage ranking;"
	},
	[51005] = {
		id = 51005,
		fmt = "5. The time-limited Boss has various types and characteristics. Please read the information of the Boss carefully before challenging.",
		fmt_th = "5. บอสที่จำกัดเวลามีประเภทและลักษณะที่หลากหลาย โปรดอ่านข้อมูลของบอสให้ละเอียดก่อนทำภารกิจ",
		fmt_en = "5. The time-limited Boss has various types and characteristics. Please read the information of the Boss carefully before challenging."
	},
	[51006] = {
		id = 51006,
		fmt = "6. It is recommended to turn on the zoom in function in the system settings when challenging the time-limited BOSS - Omnimon",
		fmt_th = "6. ขอแนะนำให้เปิดฟังก์ชั่นซูมเข้าในการตั้งค่าระบบเมื่อท้าทาย BOSS ที่จำกัดเวลา - Omnimon",
		fmt_en = "6. It is recommended to turn on the zoom in function in the system settings when challenging the time-limited BOSS - Omnimon"
	},
	[52001] = {
		id = 52001,
		fmt = "Tap (and hold) the screen left and right to perform the action",
		fmt_th = "แตะ (ค้างไว้) หน้าจอซ้ายและขวาเพื่อดำเนินการ",
		fmt_en = "Tap (and hold) the screen left and right to perform the action"
	},
	[52002] = {
		id = 52002,
		fmt = "The ancient monster moves left and right and moves one level below before its HP depletes",
		fmt_th = "สัตว์ประหลาดโบราณเคลื่อนที่ไปทางซ้ายและขวาและเคลื่อนที่ต่ำกว่าหนึ่งระดับก่อนที่ HP ของมันจะหมดลง",
		fmt_en = "The ancient monster moves left and right and moves one level below before its HP depletes"
	},
	[52003] = {
		id = 52003,
		fmt = "The higher the quantity, the more chances you have to get a higher reward.",
		fmt_th = "ยิ่งปริมาณมาก ยิ่งมีโอกาสรับรางวัลมากขึ้น",
		fmt_en = "The higher the quantity, the more chances you have to get a higher reward."
	},
	[52004] = {
		id = 52004,
		fmt = "Tap (and hold) to the left and right to move the Pokémon. Before its HP is exhausted, the more floors you go, the more chances of getting better rewards.",
		fmt_th = "แตะ (ค้างไว้) ไปทางซ้ายและขวาเพื่อย้ายโปเกมอน ก่อนที่ HP ของมันจะหมดลง ยิ่งคุณไปได้มากเท่าไร โอกาสได้รับรางวัลก็จะยิ่งมากขึ้นเท่านั้น",
		fmt_en = "Tap (and hold) to the left and right to move the Pokémon. Before its HP is exhausted, the more floors you go, the more chances of getting better rewards."
	},
	[53001] = {
		id = 53001,
		fmt = "1. Activate bond effects when you get the specific bonding Pokémons.",
		fmt_th = "1. เปิดใช้งานเอฟเฟกต์พันธะเมื่อคุณได้รับโปเกมอนพันธะเฉพาะ",
		fmt_en = "1. Activate bond effects when you get the specific bonding Pokémons."
	},
	[53002] = {
		id = 53002,
		fmt = "2. Bonds can be activated by any Pokémons needed to establish bonds that are in the same evolution series",
		fmt_th = "2. สามารถเปิดใช้งานพันธบัตรโดยโปเกมอนตัวใดก็ได้ที่จำเป็นในการสร้างพันธะที่อยู่ในซีรีย์วิวัฒนาการเดียวกัน",
		fmt_en = "2. Bonds can be activated by any Pokémons needed to establish bonds that are in the same evolution series"
	},
	[53003] = {
		id = 53003,
		fmt = "3. Even after the Pokémons required for establish bonds are decomposed, the corresponding bond effects continue to be effective",
		fmt_th = "3. แม้ว่าโปเกมอนที่จำเป็นสำหรับการสร้างพันธะจะสลายตัว เอฟเฟกต์พันธะที่เกี่ยวข้องก็ยังคงมีผลอยู่",
		fmt_en = "3. Even after the Pokémons required for establish bonds are decomposed, the corresponding bond effects continue to be effective"
	},
	[54001] = {
		id = 54001,
		fmt = "1. Activate bond effects when you get the specific bonding Pokémons.",
		fmt_th = "1. เปิดใช้งานเอฟเฟกต์พันธะเมื่อคุณได้รับโปเกมอนพันธะเฉพาะ",
		fmt_en = "1. Activate bond effects when you get the specific bonding Pokémons."
	},
	[54002] = {
