		fmt = "2. The Pro Battle is conducted in the elimination format with 4 matches, including quarterfinals, semi-finals, championship match and third place match",
		fmt_th = "2. Pro Battle ดำเนินการในรูปแบบการคัดออก มี 4 แมตช์ ได้แก่ รอบก่อนรองชนะเลิศ, รอบรองชนะเลิศ, การแข่งขันชิงแชมป์ และนัดชิงอันดับสาม",
		fmt_en = "2. The Pro Battle is conducted in the elimination format with 4 matches, including quarterfinals, semi-finals, championship match and third place match"
	},
	[78003] = {
		id = 78003,
		fmt = "3. Championship and Third Place Match are conducted concurrently",
		fmt_th = "3. การแข่งขันชิงแชมป์และอันดับสามดำเนินการพร้อมกัน",
		fmt_en = "3. Championship and Third Place Match are conducted concurrently"
	},
	[78004] = {
		id = 78004,
		fmt = "4. Duration of each match is 5 minutes",
		fmt_th = "4. ระยะเวลาของแต่ละแมตช์คือ 5 นาที",
		fmt_en = "4. Duration of each match is 5 minutes"
	},
	[78005] = {
		id = 78005,
		fmt = "5. Pokémon cannot be used repeatedly",
		fmt_th = "5. โปเกมอนไม่สามารถใช้ซ้ำได้",
		fmt_en = "5. Pokémon cannot be used repeatedly"
	},
	[79001] = {
		id = 79001,
		fmt = "1. The qualifiers, promotions and pro battles are conducted in a 3v3 tag match format.",
		fmt_th = "1. รอบคัดเลือก โปรโมชัน และการต่อสู้แบบโปรจะดำเนินการในรูปแบบการแข่งขันแท็ก 3 ต่อ 3",
		fmt_en = "1. The qualifiers, promotions and pro battles are conducted in a 3v3 tag match format."
	},
	[79002] = {
		id = 79002,
		fmt = "2. Among the Pokémons in battle, the one with the highest Speed makes the first move",
		fmt_th = "2. ในบรรดาโปเกมอนในการต่อสู้ โปเกมอนที่มีความเร็วสูงสุดจะทำการเคลื่อนไหวครั้งแรก",
		fmt_en = "2. Among the Pokémons in battle, the one with the highest Speed makes the first move"
	},
	[79003] = {
		id = 79003,
		fmt = "3. In an 1v1 battle, it last for 10 rounds at most",
		fmt_th = "3. ในการรบ 1 ต่อ 1 จะใช้เวลาไม่เกิน 10 รอบ",
		fmt_en = "3. In an 1v1 battle, it last for 10 rounds at most"
	},
	[79004] = {
		id = 79004,
		fmt = "4. If the winner is undecided at the end of the 10th round, the party with the higher HP percentage wins",
		fmt_th = "4. หากตัดสินผู้ชนะเมื่อสิ้นสุดรอบที่ 10 ปาร์ตี้ที่มีเปอร์เซ็นต์ HP สูงกว่าจะเป็นผู้ชนะ",
		fmt_en = "4. If the winner is undecided at the end of the 10th round, the party with the higher HP percentage wins"
	},
	[79005] = {
		id = 79005,
		fmt = "5. The side with surviving Pokémons wins.",
		fmt_th = "5. ฝ่ายที่มีโปเกมอนที่รอดตายจะเป็นฝ่ายชนะ",
		fmt_en = "5. The side with surviving Pokémons wins."
	},
	[80001] = {
		id = 80001,
		fmt = "1. Players can begin betting for qualifying matches on the first day of the tournament",
		fmt_th = "1. ผู้เล่นสามารถเริ่มเดิมพันการแข่งขันรอบคัดเลือกได้ในวันแรกของการแข่งขัน",
		fmt_en = "1. Players can begin betting for qualifying matches on the first day of the tournament"
	},
	[80002] = {
		id = 80002,
		fmt = "2. Betting time for qualifiers is on the 1st day of the tournament at 10:00-18:50",
		fmt_th = "2. เวลาเดิมพันสำหรับรอบคัดเลือกคือวันที่ 1 ของการแข่งขัน เวลา 10.00-18:50 น",
		fmt_en = "2. Betting time for qualifiers is on the 1st day of the tournament at 10:00-18:50"
	},
	[80003] = {
		id = 80003,
		fmt = "3. Make a bet and guess the players who will emerge in the top three with most number of points at the end of the qualifiers",
		fmt_th = "3. วางเดิมพันและเดาผู้เล่นที่จะอยู่ในสามอันดับแรกด้วยคะแนนสูงสุดเมื่อสิ้นสุดรอบคัดเลือก",
		fmt_en = "3. Make a bet and guess the players who will emerge in the top three with most number of points at the end of the qualifiers"
	},
	[80004] = {
		id = 80004,
		fmt = "4. Players can make a bet on up to 3 players",
		fmt_th = "4. ผู้เล่นสามารถวางเดิมพันได้สูงสุด 3 ผู้เล่น",
		fmt_en = "4. Players can make a bet on up to 3 players"
	},
	[80005] = {
		id = 80005,
		fmt = "5. Double of the bet will be returned if players make a correct guess. Otherwise, half of the bet will be returned.",
		fmt_th = "5. เงินเดิมพันสองเท่าจะได้รับคืนหากผู้เล่นทายถูก มิฉะนั้นจะคืนเงินเดิมพันครึ่งหนึ่ง",
		fmt_en = "5. Double of the bet will be returned if players make a correct guess. Otherwise, half of the bet will be returned."
	},
	[80006] = {
		id = 80006,
		fmt = "6. Players get additional rewards for guessing all 3 contestants correctly",
		fmt_th = "6. ผู้เล่นจะได้รับรางวัลเพิ่มเติมจากการทายผู้เข้าแข่งขันทั้ง 3 คนให้ถูกต้อง",
		fmt_en = "6. Players get additional rewards for guessing all 3 contestants correctly"
	},
	[81001] = {
