		fmt = "1. Players can make their bets on the semi-finals on the 2nd day of the tournament",
		fmt_th = "1. ผู้เล่นสามารถวางเดิมพันในรอบรองชนะเลิศได้ในวันที่ 2 ของการแข่งขัน",
