	[95001] = {
		id = 95001,
		fmt = "1. Some Pokémon in the Handbook can be Mega Evolved in the Mega Evolve Room.",
		fmt_th = "1. โปเกมอนบางตัวในคู่มือสามารถพัฒนาเป็นเมก้าได้ในห้องวิวัฒนาการเมก้า",
		fmt_en = "1. Some Pokémon in the Handbook can be Mega Evolved in the Mega Evolve Room."
	},
	[95002] = {
		id = 95002,
		fmt = "2. Mega Evolved Pokémon has higher base stats with all trained stats. Its Type and Rarity #C0xF76B45##L10#may also change#C0x5B545B#.",
		fmt_th = "2. Mega Evolved Pokémon มีสเตตัสหลักที่สูงกว่าด้วยสถิติที่ฝึกฝนมาทั้งหมด ประเภทและความหายากของมัน #C0xF76B45##L10# อาจเปลี่ยนแปลง#C0x5B545B#ด้วย",
		fmt_en = "2. Mega Evolved Pokémon has higher base stats with all trained stats. Its Type and Rarity #C0xF76B45##L10#may also change#C0x5B545B#."
	},
	[95003] = {
		id = 95003,
		fmt = "3. Pokémon has to be trained before Mega Evolving. Mega Evolve consumes 2 kinds of items: Keystone and exclusive Mega Evolve Stone.",
		fmt_th = "3. โปเกมอนต้องได้รับการฝึกฝนก่อน Mega Evolving Mega Evolve ใช้ไอเทม 2 ชนิด: Keystone และ Mega Evolve Stone สุดพิเศษ",
		fmt_en = "3. Pokémon has to be trained before Mega Evolving. Mega Evolve consumes 2 kinds of items: Keystone and exclusive Mega Evolve Stone."
	},
	[95004] = {
		id = 95004,
		fmt = "4. These items are available at Mega Evolve Room from Convert.",
		fmt_th = "4. ไอเทมเหล่านี้หาได้จาก Mega Evolve Room จาก Convert",
		fmt_en = "4. These items are available at Mega Evolve Room from Convert."
	},
	[95005] = {
		id = 95005,
		fmt = "5. New Mega Evolve Pokémon are introduced occasionally. Please stay tuned.",
		fmt_th = "5. มีการแนะนำโปเกมอน Mega Evolve ใหม่เป็นครั้งคราว โปรดคอยติดตาม",
		fmt_en = "5. New Mega Evolve Pokémon are introduced occasionally. Please stay tuned."
	},
	[96001] = {
		id = 96001,
		fmt = "1. Keystones are available from converting #C0xF76B45##L10#Pokémon with the same Rarity#C0x5B545B# or #C0xF76B45##L10#Shard of Pokémon with the same Rarity#C0x5B545B#. Daily converts limited:",
		fmt_th = "1. คีย์สโตนสามารถแปลงได้จากการแปลง #C0xF76B45##L10#โปเกมอนที่มีความหายากเท่ากัน#C0x5B545B# หรือ #C0xF76B45##L10#Shard ของโปเกมอนที่มีความหายาก#C0x5B545B# เท่ากัน จำกัดการแปลงรายวัน:",
		fmt_en = "1. Keystones are available from converting #C0xF76B45##L10#Pokémon with the same Rarity#C0x5B545B# or #C0xF76B45##L10#Shard of Pokémon with the same Rarity#C0x5B545B#. Daily converts limited:"
	},
	[96002] = {
		id = 96002,
