		fmt_th = "①1 โปเกมอนระดับ A หรือ Purple Ditto สามารถแปลงเป็น Purple Evolve Keystones 10 อัน; 3 ชิ้นส่วน Rank-A สามารถแปลงเป็น 1 Purple Evolve Keystone",
		fmt_en = "①1 Rank-A Pokémon or Purple Ditto can be converted into 10 Purple Evolve Keystones; 3 Rank-A Shards can be converted into 1 Purple Evolve Keystone."
	},
	[96003] = {
		id = 96003,
		fmt = "②1 Rank-S Pokémon or Orange Ditto can be converted into 10 Orange Evolve Keystones; 5 Rank-S Shards can be converted into 1 Orange Evolve Keystone.",
		fmt_th = "②1 โปเกมอนแรงค์ S หรือ Orange Ditto สามารถแปลงเป็น 10 Orange Evolve Keystones; 5 Rank-S Shards สามารถแปลงเป็น 1 Orange Evolve Keystone",
		fmt_en = "②1 Rank-S Pokémon or Orange Ditto can be converted into 10 Orange Evolve Keystones; 5 Rank-S Shards can be converted into 1 Orange Evolve Keystone."
