		fmt = "2. Diamond Purchases for Convertible Keystones reset at 5am every day. Stackable with limit.",
		fmt_th = "2.  Diamond การซื้อ Convertible Keystones จะรีเซ็ตเวลาตี 5 ทุกวัน วางซ้อนกันได้โดยมีขีดจำกัด",
		fmt_en = "2. Diamond Purchases for Convertible Keystones reset at 5am every day. Stackable with limit."
