	[97001] = {
		id = 97001,
		fmt = "1. Exclusive Super Stones are available by consuming #C0xF76B45##L10#Pokémon with the same Type and Rarity#C0x5B545B# or converting #C0xF76B45##L10#Shards of Pokémon with the same Type and Rarity#C0x5B545B#. Daily converts limited:",
