	},
	[97002] = {
		id = 97002,
		fmt = "①1 Rank-A Pokémon with the same Type or Purple Ditto can be converted into 10 Purple Super Stones; 3 Rank-A Shards can be converted into 1 Purple Super Sone.",
		fmt_th = "①1 โปเกมอนแรงค์-A ที่มีประเภทเดียวกันหรือสีม่วงเหมือนกันสามารถแปลงเป็น Purple Super Stone 10 อัน; 3 ชิ้นส่วน Rank-A สามารถแปลงเป็น Purple Super Sone 1 อัน",
		fmt_en = "①1 Rank-A Pokémon with the same Type or Purple Ditto can be converted into 10 Purple Super Stones; 3 Rank-A Shards can be converted into 1 Purple Super Sone."
	},
	[97003] = {
		id = 97003,
		fmt = "②1 Rank-S Pokémon with the same Type or Orange Ditto can be converted into 10 Orange Super Stones; 5 Rank-S Shards can be converted into 1 Orange Super Stone.",
		fmt_th = "②1 โปเกมอนแรงค์-S ที่มีประเภทเดียวกันหรือเหมือนกันสีส้มสามารถเปลี่ยนเป็น 10 ซุปเปอร์สโตนสีส้ม; 5 Rank-S Shards สามารถแปลงเป็น 1 Orange Super Stone",
		fmt_en = "②1 Rank-S Pokémon with the same Type or Orange Ditto can be converted into 10 Orange Super Stones; 5 Rank-S Shards can be converted into 1 Orange Super Stone."
	},
	[97004] = {
		id = 97004,
		fmt = "③1 Rank-S+ Pokémon with the same Type or Red Ditto can be converted into 10 Red Super Stones; 8 Rank-S+ Shards can be converted into 1 Red Super Stone.",
		fmt_th = "③1 โปเกมอนระดับ S+ ที่มีประเภทเดียวกันหรือสีแดงเหมือนกันสามารถแปลงเป็น Red Super Stone 10 อัน; 8 Rank-S+ Shards สามารถแปลงเป็น Red Super Stone 1 อัน",
		fmt_en = "③1 Rank-S+ Pokémon with the same Type or Red Ditto can be converted into 10 Red Super Stones; 8 Rank-S+ Shards can be converted into 1 Red Super Stone."
	},
	[97005] = {
		id = 97005,
		fmt = "3. Different Super Stones have different converts limit.",
		fmt_th = "3. Super Stone ที่แตกต่างกันมีขีดจำกัดการแปลงที่แตกต่างกัน",
		fmt_en = "3. Different Super Stones have different converts limit."
	},
	[97006] = {
		id = 97006,
		fmt = "4. The number of convertible Super Stones reset at 5am every day and those that is purchased is stackable, but cannot exceed the limit.",
		fmt_th = "4. จำนวน Super Stone ที่ปรับเปลี่ยนได้จะรีเซ็ตเวลา 05.00 น. ทุกวัน และจำนวนที่ซื้อจะซ้อนกันได้ แต่ไม่เกินขีดจำกัด",
		fmt_en = "4. The number of convertible Super Stones reset at 5am every day and those that is purchased is stackable, but cannot exceed the limit."
