	[98001] = {
		id = 98001,
		fmt = "1. PvP Arena conducts #C0xF76B45#Cross-server Matchup Battle#C0x5B545B#. When being matched up, you will see #C0xF76B45#Match Found. Please wait...",
		fmt_th = "1. PvP Arena ดำเนินการ #C0xF76B45# การต่อสู้แบบจับคู่ข้ามเซิร์ฟเวอร์#C0x5B545B# เมื่อจับคู่แล้ว คุณจะเห็น #C0xF76B45# พบการจับคู่ โปรดรอ...",
		fmt_en = "1. PvP Arena conducts #C0xF76B45#Cross-server Matchup Battle#C0x5B545B#. When being matched up, you will see #C0xF76B45#Match Found. Please wait..."
	},
	[98002] = {
		id = 98002,
		fmt = "2. Season Schedule of PvP Arena #C0xF76B45#Announcement of a Season → Season in progress → Season Ended, Ranking Display. The season usually lasts a few weeks. You may check it above your Image.",
		fmt_th = "2. ตารางฤดูกาลของ PvP Arena #C0xF76B45# ประกาศของฤดูกาล → ฤดูกาลที่กำลังดำเนินอยู่ → สิ้นสุดฤดูกาล แสดงอันดับ ฤดูกาลมักจะใช้เวลาสองสามสัปดาห์ คุณสามารถตรวจสอบได้เหนือรูปภาพของคุณ",
		fmt_en = "2. Season Schedule of PvP Arena #C0xF76B45#Announcement of a Season → Season in progress → Season Ended, Ranking Display. The season usually lasts a few weeks. You may check it above your Image."
	},
	[98003] = {
		id = 98003,
		fmt = "3. There is no limit to the number of matchup battles within each week. Players can only participate during match time. #C0xF76B45#You can check the time to find a match below the Start Match button.",
		fmt_th = "3. ไม่มีการจำกัดจำนวนของการต่อสู้แบบจับคู่ภายในแต่ละสัปดาห์ ผู้เล่นสามารถเข้าร่วมได้ในช่วงเวลาการแข่งขันเท่านั้น #C0xF76B45#คุณสามารถตรวจสอบเวลาเพื่อค้นหาการแข่งขันที่ด้านล่างปุ่มเริ่มการแข่งขัน",
		fmt_en = "3. There is no limit to the number of matchup battles within each week. Players can only participate during match time. #C0xF76B45#You can check the time to find a match below the Start Match button."
	},
	[98004] = {
		id = 98004,
		fmt = "4. PvP Arena conducts #C0xF76B45#Real-time Matchup Battle#C0x5B545B#. Players need to tap Start Match manually and stay online while fighting.",
		fmt_th = "4. PvP Arena ดำเนินการ #C0xF76B45#การต่อสู้แบบแมตช์แบบเรียลไทม์#C0x5B545B# ผู้เล่นต้องแตะ Start Match ด้วยตนเองและออนไลน์ขณะต่อสู้",
		fmt_en = "4. PvP Arena conducts #C0xF76B45#Real-time Matchup Battle#C0x5B545B#. Players need to tap Start Match manually and stay online while fighting."
	},
	[98005] = {
		id = 98005,
		fmt = "5. With the #C0xF76B45#Points System#C0x5B545B#, the higher the success rate, the more points will be scored. Players will be ranked by points.#C0xF76B45#2 Modes of Arena are scoring and ranking independently.",
		fmt_th = "5. ด้วย #C0xF76B45#Points System#C0x5B545B# ยิ่งอัตราความสำเร็จสูงขึ้น คะแนนก็จะยิ่งมากขึ้น ผู้เล่นจะถูกจัดอันดับตามคะแนน#C0xF76B45#2 โหมดของอารีน่าทำการให้คะแนนและจัดอันดับอย่างอิสระ",
		fmt_en = "5. With the #C0xF76B45#Points System#C0x5B545B#, the higher the success rate, the more points will be scored. Players will be ranked by points.#C0xF76B45#2 Modes of Arena are scoring and ranking independently."
	},
	[98006] = {
		id = 98006,
		fmt = "6. At the start of each Season, the highest record and points of players under 2 modes from last Season will be cleared.",
		fmt_th = "6. เมื่อเริ่มต้นแต่ละฤดูกาล สถิติสูงสุดและคะแนนของผู้เล่นภายใต้ 2 โหมดจากฤดูกาลที่แล้วจะถูกล้าง",
		fmt_en = "6. At the start of each Season, the highest record and points of players under 2 modes from last Season will be cleared."
	},
	[99001] = {
		id = 99001,
		fmt = "1. There are 2 modes in the PvP Arena: #C0xF76B45#Unlimited Match and Pick Match#C0x5B545B#",
		fmt_th = "1. มี 2 โหมดใน PvP Arena: #C0xF76B45#Unlimited Match and Pick Match#C0x5B545B#",
		fmt_en = "1. There are 2 modes in the PvP Arena: #C0xF76B45#Unlimited Match and Pick Match#C0x5B545B#"
	},
	[99002] = {
		id = 99002,
		fmt = "2. Unlimited Match requires to #C0xF76B45#preset the Lineup#C0x5B545B# and fight manually.",
		fmt_th = "2. แมตช์ไม่จำกัดต้อง #C0xF76B45# ตั้งค่า Lineup#C0x5B545B# ล่วงหน้าและต่อสู้ด้วยตนเอง",
		fmt_en = "2. Unlimited Match requires to #C0xF76B45#preset the Lineup#C0x5B545B# and fight manually."
	},
	[99003] = {
		id = 99003,
		fmt = "3. Pick Match has #C0xF76B45#Theme Gameplay (Theme changes every week or every few weeks but points still accumulate)",
		fmt_th = "3. Pick Match มี #C0xF76B45# รูปแบบการเล่นเกม (ธีมจะเปลี่ยนทุกสัปดาห์หรือทุกสองสามสัปดาห์ แต่คะแนนยังคงสะสมอยู่)",
		fmt_en = "3. Pick Match has #C0xF76B45#Theme Gameplay (Theme changes every week or every few weeks but points still accumulate)"
	},
	[99004] = {
		id = 99004,
		fmt = "4. Pick Match has two picking modes: #C0xF76B45#Pick Mode and Ban&Pick Mode. When points reach a certain amount, it can be automatically upgraded to Ban (no changes to theme). Tap i below Toggle Button in the Pick Match for more details.",
		fmt_th = "4. Pick Match มีสองโหมดการเลือก: #C0xF76B45% 23Pick Mode และ Ban&Pick Mode เมื่อแต้มถึงจำนวนที่กำหนด จะสามารถอัปเกรดเป็นแบนได้โดยอัตโนมัติ (ไม่มีการเปลี่ยนแปลงธีม) แตะ i ด้านล่างปุ่มสลับใน Pick Match เพื่อดูรายละเอียดเพิ่มเติม",
		fmt_en = "4. Pick Match has two picking modes: #C0xF76B45#Pick Mode and Ban&Pick Mode. When points reach a certain amount, it can be automatically upgraded to Ban (no changes to theme). Tap i below Toggle Button in the Pick Match for more details."
	},
	[99005] = {
		id = 99005,
		fmt = "5. Pick Match requires to preset the alternative Lineup. #C0xF76B45#Insufficient Pokémon will result in a failed matchup. Alternative Lineup decides which Pokémon are available for Ban&Pick Mode.",
		fmt_th = "5. Pick Match ต้องตั้งค่าล่วงหน้า Lineup สำรอง #C0xF76B45#โปเกมอนไม่เพียงพอจะส่งผลให้การจับคู่ล้มเหลว รายชื่อสำรองจะตัดสินว่าโปเกมอนตัวใดที่สามารถใช้ได้ในโหมดแบน&เลือก",
		fmt_en = "5. Pick Match requires to preset the alternative Lineup. #C0xF76B45#Insufficient Pokémon will result in a failed matchup. Alternative Lineup decides which Pokémon are available for Ban&Pick Mode."
	},
	[99006] = {
		id = 99006,
		fmt = "6. Unlimited Match and Pick Match are both played in #C0xF76B45#6v6#C0x5B545B# mode. #C0xF76B45#Stats of Pokémon#C0x5B545B# will be adjusted fairly in Fair Tournament as well as their Rarity. The Speed of Pokémon decides the order of action.",
		fmt_th = "6. แมตช์และเลือกแมตช์ไม่จำกัดเล่นในโหมด #C0xF76B45#6v6#C0x5B545B# #C0xF76B45#สถิติของโปเกมอน#C0x5B545B# จะถูกปรับอย่างเป็นธรรมในทัวร์นาเมนต์ที่ยุติธรรมและระดับความหายาก ความเร็วของโปเกมอนเป็นตัวกำหนดลำดับการกระทำ",
		fmt_en = "6. Unlimited Match and Pick Match are both played in #C0xF76B45#6v6#C0x5B545B# mode. #C0xF76B45#Stats of Pokémon#C0x5B545B# will be adjusted fairly in Fair Tournament as well as their Rarity. The Speed of Pokémon decides the order of action."
	},
	[99007] = {
		id = 99007,
		fmt = "7. Stats of #C0xF76B45#Carried Item, Rune and Character#C0x5B545B# are all invalid in Pick Match. Guild Skills, Talent Skills and Device Stats will be adjusted fairly.",
		fmt_th = "7. สถิติ #C0xF76B45# ไอเทมที่บรรทุก รูน และตัวละคร#C0x5B545B# ทั้งหมดไม่ถูกต้องในการจับคู่แบบเลือก ทักษะกิลด์ ทักษะความสามารถ และสถิติ  Device จะถูกปรับอย่างเป็นธรรม",
		fmt_en = "7. Stats of #C0xF76B45#Carried Item, Rune and Character#C0x5B545B# are all invalid in Pick Match. Guild Skills, Talent Skills and Device Stats will be adjusted fairly."
	},
	[99008] = {
		id = 99008,
		fmt = "8. Unlimited Match and Pick Match are both played #C0xF76B45#manually#C0x5B545B#. Players need to set Pokémon skills before the countdown ends then start auto-fighting.",
		fmt_th = "8. แมตช์ไม่จำกัดและแมตช์เลือกเล่น #C0xF76B45# ด้วยตนเอง#C0x5B545B# ผู้เล่นจำเป็นต้องตั้งค่าทักษะโปเกมอนก่อนการนับถอยหลังจะสิ้นสุดลง จากนั้นจึงเริ่มการต่อสู้อัตโนมัติ",
		fmt_en = "8. Unlimited Match and Pick Match are both played #C0xF76B45#manually#C0x5B545B#. Players need to set Pokémon skills before the countdown ends then start auto-fighting."
	},
	[99009] = {
		id = 99009,
		fmt = "9. The battle of both Unlimited Match and Pick Match lasts up to 20 rounds. Players whose Pokémon are all knocked out loses. If there is no winner at the end of the round, the one with the highest HP wins.",
		fmt_th = "9. การต่อสู้ของ Unlimited Match และ Pick Match นานถึง 20 รอบ ผู้เล่นที่ล้มโปเกมอนทั้งหมดจะแพ้ หากไม่มีผู้ชนะเมื่อสิ้นสุดรอบ ผู้ที่มี HP สูงสุดจะเป็นผู้ชนะ",
		fmt_en = "9. The battle of both Unlimited Match and Pick Match lasts up to 20 rounds. Players whose Pokémon are all knocked out loses. If there is no winner at the end of the round, the one with the highest HP wins."
	},
	[100001] = {
		id = 100001,
		fmt = "1. During match time, #C0xF76B45#the first 6 battles every day#C0x5B545B# grant Settlement Reward whether win or lose.",
		fmt_th = "1. ในช่วงเวลาการแข่งขัน #C0xF76B45#การรบ 6 ครั้งแรกทุกวัน#C0x5B545B# มอบรางวัลการตั้งถิ่นฐานไม่ว่าจะชนะหรือแพ้",
		fmt_en = "1. During match time, #C0xF76B45#the first 6 battles every day#C0x5B545B# grant Settlement Reward whether win or lose."
	},
	[100002] = {
		id = 100002,
		fmt = "2. The weekly #C0xF76B45#Target Reward can be claimed at Pack on the bottom right of the screen#C0x5B545B#. Complete easy matchup quests to claim it.",
		fmt_th = "2. สามารถรับรางวัล #C0xF76B45#Target Reward รายสัปดาห์ได้ที่แพ็คที่ด้านล่างขวาของหน้าจอ#C0x5B545B# ทำภารกิจจับคู่ง่าย ๆ เพื่อรับสิทธิ์",
		fmt_en = "2. The weekly #C0xF76B45#Target Reward can be claimed at Pack on the bottom right of the screen#C0x5B545B#. Complete easy matchup quests to claim it."
	},
	[100003] = {
		id = 100003,
		fmt = "3. #C0xF76B45#Weekly settlement rewards will be sent in 30 min after matchup on Sunday#C0x5B545B# to players with higher points in 2 modes. #C0xF76B45#Note: Only players who participated in at least 3 matches (any mode) a week are eligible to claim rewards.",
		fmt_th = "3. #C0xF76B45#รางวัลการชำระเงินรายสัปดาห์จะถูกส่งภายใน 30 นาทีหลังจากการจับคู่ในวันอาทิตย์#C0x5B545B# ไปยังผู้เล่นที่มีคะแนนสูงกว่าใน 2 โหมด #C0xF76B45#หมายเหตุ: เฉพาะผู้เล่นที่เข้าร่วมอย่างน้อย 3 แมตช์ (โหมดใดก็ได้) ต่อสัปดาห์จึงจะมีสิทธิ์รับรางวัล",
		fmt_en = "3. #C0xF76B45#Weekly settlement rewards will be sent in 30 min after matchup on Sunday#C0x5B545B# to players with higher points in 2 modes. #C0xF76B45#Note: Only players who participated in at least 3 matches (any mode) a week are eligible to claim rewards."
	},
	[100004] = {
		id = 100004,
		fmt = "4. #C0xF76B45#Final settlement rewards will be sent in 30 min after match on the last day of the Season#C0x5B545B# to players with higher ranks in 2 modes. #C0xF76B45#Note: Only players who participated in at least 1 match (any mode) during the Season are eligible to claim rewards.",
		fmt_th = "4. #C0xF76B45#รางวัลการชำระบัญชีสุดท้ายจะถูกส่งใน 30 นาทีหลังจากการแข่งขันในวันสุดท้ายของฤดูกาล#C0x5B545B# ไปยังผู้เล่นที่มีอันดับสูงกว่าใน 2 โหมด #C0xF76B45#หมายเหตุ: เฉพาะผู้เล่นที่เข้าร่วมอย่างน้อย 1 แมตช์ (โหมดใดก็ได้) ระหว่างฤดูกาลเท่านั้นจึงจะมีสิทธิ์รับรางวัล",
		fmt_en = "4. #C0xF76B45#Final settlement rewards will be sent in 30 min after match on the last day of the Season#C0x5B545B# to players with higher ranks in 2 modes. #C0xF76B45#Note: Only players who participated in at least 1 match (any mode) during the Season are eligible to claim rewards."
	},
	[100005] = {
		id = 100005,
		fmt = "5. Currency can be used in PvP Arena Shop. #C0xF76B45#Earn more points to permanently unlock more items!",
		fmt_th = "5. สกุลเงินสามารถใช้ได้ในร้านค้า PvP Arena #C0xF76B45#รับคะแนนเพิ่มเพื่อปลดล็อกไอเท็มเพิ่มเติมอย่างถาวร!",
		fmt_en = "5. Currency can be used in PvP Arena Shop. #C0xF76B45#Earn more points to permanently unlock more items!"
	},
	[111001] = {
		id = 111001,
		fmt = "1. Upgrading Badge increases Stats of all Pokémon. Challenge Gym now and get some upgrade materials!",
		fmt_th = "1. การอัพเกรดตราเพิ่มสถิติของโปเกมอนทั้งหมด ท้าทายยิมตอนนี้และรับวัสดุอัปเกรด!",
		fmt_en = "1. Upgrading Badge increases Stats of all Pokémon. Challenge Gym now and get some upgrade materials!"
	},
	[111002] = {
		id = 111002,
		fmt = "2. The number of Badges is equal to the number of gyms. 4 Badges are unlocked by default. Activates Badge Spirit to the certain level to unlock new Badges.",
		fmt_th = "2. จำนวนเหรียญตราเท่ากับจำนวนโรงยิม 4 ป้ายจะถูกปลดล็อคโดยค่าเริ่มต้น เปิดใช้งาน Badge Spirit จนถึงระดับหนึ่งเพื่อปลดล็อค Badges ใหม่",
		fmt_en = "2. The number of Badges is equal to the number of gyms. 4 Badges are unlocked by default. Activates Badge Spirit to the certain level to unlock new Badges."
	},
	[111003] = {
		id = 111003,
		fmt = "3. Each Badge requires Guard Pokémon. The development of Guard Pokémon affects extra Badge Stats Boost.",
		fmt_th = "3. แต่ละตราต้องใช้โปเกมอน  Guard การพัฒนาโปเกมอน  Guard จะส่งผลต่อการเพิ่มสถานะป้ายพิเศษ",
		fmt_en = "3. Each Badge requires Guard Pokémon. The development of Guard Pokémon affects extra Badge Stats Boost."
	},
	[111004] = {
		id = 111004,
		fmt = "4. Awaken Badge to activate more Guard Pokémon slots.",
		fmt_th = "4. Awaken Badge เพื่อเปิดใช้งานสล็อตโปเกมอน  Guard เพิ่มเติม",
		fmt_en = "4. Awaken Badge to activate more Guard Pokémon slots."
	},
	[101001] = {
		id = 101001,
		fmt = "1. During the event, Returned Trainer can link with #C0xF76B45#a Pro Trainer#C0x5B545B#. #C0xF76B45#Cannot undo.",
		fmt_th = "1. ในช่วงกิจกรรม ผู้ฝึกสอนที่กลับมาสามารถเชื่อมโยงกับ #C0xF76B45#a Pro Trainer#C0x5B545B# #C0xF76B45#ไม่สามารถยกเลิกได้",
		fmt_en = "1. During the event, Returned Trainer can link with #C0xF76B45#a Pro Trainer#C0x5B545B#. #C0xF76B45#Cannot undo."
	},
	[101002] = {
		id = 101002,
		fmt = "2. Pro Trainer must be Lv.55 with more than 150,000 of Power before linking with a Returned Trainer.",
		fmt_th = "2. Pro Trainer จะต้องมี Lv.55 ที่มีพลังมากกว่า 150,000 ก่อนทำการเชื่อมโยงกับ Trainer ที่ส่งคืน",
		fmt_en = "2. Pro Trainer must be Lv.55 with more than 150,000 of Power before linking with a Returned Trainer."
	},
	[101003] = {
		id = 101003,
		fmt = "3. After linked, Co-op Quests and Personal Quests are both #C0xF76B45#available to the Returned Trainer. However, the Pro Trainer can only access to Co-op Quests.",
		fmt_th = "3. หลังจากเชื่อมโยงแล้ว ภารกิจ Co-op และภารกิจส่วนตัวจะพร้อมใช้งาน #C0xF76B45# สำหรับผู้ฝึกที่ส่งคืน อย่างไรก็ตาม Pro Trainer สามารถเข้าถึง Co-op Quests เท่านั้น",
		fmt_en = "3. After linked, Co-op Quests and Personal Quests are both #C0xF76B45#available to the Returned Trainer. However, the Pro Trainer can only access to Co-op Quests."
	},
	[101004] = {
		id = 101004,
		fmt = "4. Once a quest is complete, #C0xF76B45#both trainers will receive Quest Points#C0x5B545B#. #C0xF76B45#Trainers must work together and earn more points to unlock the Reunion Chest.",
		fmt_th = "4. เมื่อภารกิจเสร็จสิ้น #C0xF76B45#ผู้ฝึกสอนทั้งคู่จะได้รับคะแนนภารกิจ#C0x5B545B# #C0xF76B45#ผู้ฝึกสอนต้องทำงานร่วมกันและได้รับคะแนนมากขึ้นเพื่อปลดล็อกหีบสมบัติเรอูนียง",
		fmt_en = "4. Once a quest is complete, #C0xF76B45#both trainers will receive Quest Points#C0x5B545B#. #C0xF76B45#Trainers must work together and earn more points to unlock the Reunion Chest."
	},
	[101005] = {
		id = 101005,
		fmt = "5. Trainers #C0xF76B45#can join the event only once#C0x5B545B#. After the event, Pro Trainer cannot join again before CD ends.",
		fmt_th = "5. เทรนเนอร์ #C0xF76B45#สามารถเข้าร่วมกิจกรรมได้เพียงครั้งเดียว#C0x5B545B# หลังจบกิจกรรม Pro Trainer จะไม่สามารถเข้าร่วมได้อีกก่อนที่ซีดีจะสิ้นสุด",
		fmt_en = "5. Trainers #C0xF76B45#can join the event only once#C0x5B545B#. After the event, Pro Trainer cannot join again before CD ends."
	},
	[101006] = {
		id = 101006,
		fmt = "6. If the event is not completed due to the inactivity of Returned Player, the linked Pro Trainer can enjoy a shorter CD.",
		fmt_th = "6. หากกิจกรรมไม่เสร็จสิ้นเนื่องจากไม่มีการใช้งานของผู้เล่นที่ส่งคืน Pro Trainer ที่เชื่อมโยงสามารถเพลิดเพลินกับซีดีที่สั้นลงได้",
		fmt_en = "6. If the event is not completed due to the inactivity of Returned Player, the linked Pro Trainer can enjoy a shorter CD."
	},
	[101007] = {
		id = 101007,
		fmt = "7. #C0xF76B45#Any unclaimed rewards will not be sent through mail#C0x5B545B#. Please claim them in time!",
		fmt_th = "7. #C0xF76B45#ของรางวัลที่ไม่มีการอ้างสิทธิ์จะไม่ถูกส่งทางไปรษณีย์#C0x5B545B# กรุณาเรียกร้องพวกเขาในเวลา!",
		fmt_en = "7. #C0xF76B45#Any unclaimed rewards will not be sent through mail#C0x5B545B#. Please claim them in time!"
	},
	[102001] = {
		id = 102001,
		fmt = "#C0xF76B45#【Gym Basic Rules】",
		fmt_th = "#C0xF76B45#【กฎพื้นฐานของยิม】",
		fmt_en = "#C0xF76B45#【Gym Basic Rules】"
	},
	[102002] = {
		id = 102002,
		fmt = "1. Gym Opening Hours: #C0xF76B45#Mon 10:00#C0x5B545B# to #C0xF76B45#Sun 21:45#C0x5B545B#; Players cannot challenge Gym Dungeon or fight for Honorary Gym Leader when the Gym is closed. Gyms reset at 5am every Monday.",
		fmt_th = "1. เวลาเปิดทำการของยิม: #C0xF76B45#จันทร์ 10:00#C0x5B545B# ถึง #C0xF76B45#อา 21:45#C0x5B545B#; ผู้เล่นไม่สามารถท้าทาย Gym Dungeon หรือต่อสู้เพื่อ Honorary Gym Leader เมื่อยิมถูกปิด ยิมจะรีเซ็ตเวลา 05.00 น. ทุกวันจันทร์",
		fmt_en = "1. Gym Opening Hours: #C0xF76B45#Mon 10:00#C0x5B545B# to #C0xF76B45#Sun 21:45#C0x5B545B#; Players cannot challenge Gym Dungeon or fight for Honorary Gym Leader when the Gym is closed. Gyms reset at 5am every Monday."
	},
	[102003] = {
		id = 102003,
		fmt = "2. Gym Dungeon has limited challenge attempts. Attempts will only be deducted after the successful challenge. It resets at 5am every day.",
		fmt_th = "2. Gym Dungeon มีความท้าทายที่จำกัด ความพยายามจะถูกหักหลังจากความท้าทายที่ประสบความสำเร็จเท่านั้น มันรีเซ็ตเวลาตี 5 ทุกวัน",
		fmt_en = "2. Gym Dungeon has limited challenge attempts. Attempts will only be deducted after the successful challenge. It resets at 5am every day."
	},
	[102004] = {
		id = 102004,
		fmt = "3. There are 8 different Gyms and each Gym has 5 Dungeons.",
		fmt_th = "3. มียิมทั้งหมด 8 แห่ง และยิมแต่ละแห่งมี 5 ดันเจี้ยน",
		fmt_en = "3. There are 8 different Gyms and each Gym has 5 Dungeons."
	},
	[102005] = {
		id = 102005,
		fmt = "4. Gym Dungeon cannot be challenged repeatedly. The Stats of Gym mobs are related to player's power. Mobs and their stats are refreshed after reset.",
		fmt_th = "4. Gym Dungeon ไม่สามารถท้าทายซ้ำได้ สถิติม็อบยิมเกี่ยวข้องกับพลังของผู้เล่น Mobs และสถิติจะรีเฟรชหลังจากรีเซ็ต",
		fmt_en = "4. Gym Dungeon cannot be challenged repeatedly. The Stats of Gym mobs are related to player's power. Mobs and their stats are refreshed after reset."
	},
	[102006] = {
		id = 102006,
		fmt = "5. After challenging all difficulties of a Gym, players can fight for the Honorary Gym Leader of that Gym.",
		fmt_th = "5. หลังจากท้าทายความยากทั้งหมดของยิมแล้ว ผู้เล่นสามารถต่อสู้เพื่อเป็นผู้นำยิมกิตติมศักดิ์ของยิมนั้นได้",
		fmt_en = "5. After challenging all difficulties of a Gym, players can fight for the Honorary Gym Leader of that Gym."
	},
	[102007] = {
		id = 102007,
		fmt = "6. Each Gym can only have 1 Honorary Gym Leader and each player can only become Honorary Gym Leader of one Gym. When a player becomes the Leader of a new Gym, the Lineup in another Gym will be removed.",
		fmt_th = "6. โรงยิมแต่ละแห่งสามารถมีผู้นำยิมกิตติมศักดิ์ได้ 1 คน และผู้เล่นแต่ละคนสามารถเป็นหัวหน้ายิมกิตติมศักดิ์ของยิมได้เพียงแห่งเดียวเท่านั้น เมื่อผู้เล่นกลายเป็นหัวหน้ายิมใหม่ ผู้เล่นตัวจริงในยิมอื่นจะถูกลบออก",
		fmt_en = "6. Each Gym can only have 1 Honorary Gym Leader and each player can only become Honorary Gym Leader of one Gym. When a player becomes the Leader of a new Gym, the Lineup in another Gym will be removed."
	},
	[102008] = {
		id = 102008,
		fmt = "7. After successfully challenging the Honorary Gym Leader, players will have to wait some time before challenging again. However, challenge attempts are unlimited.",
		fmt_th = "7. หลังจากประสบความสำเร็จในการท้าทายผู้นำยิมกิตติมศักดิ์ ผู้เล่นจะต้องรอสักครู่ก่อนที่จะท้าทายอีกครั้ง อย่างไรก็ตาม ความพยายามในการท้าทายนั้นไม่จำกัด",
		fmt_en = "7. After successfully challenging the Honorary Gym Leader, players will have to wait some time before challenging again. However, challenge attempts are unlimited."
	},
	[102009] = {
		id = 102009,
		fmt = "8. Gym Leader Challenge requires Pokémon with designated types (either first type or second type will do). Challenge is not available without qualified Pokémon.",
		fmt_th = "8. Gym Leader Challenge ต้องใช้โปเกมอนที่มีประเภทที่กำหนด (ประเภทที่หนึ่งหรือประเภทที่สองจะทำ) ความท้าทายไม่สามารถทำได้หากไม่มีโปเกมอนที่ผ่านการรับรอง",
		fmt_en = "8. Gym Leader Challenge requires Pokémon with designated types (either first type or second type will do). Challenge is not available without qualified Pokémon."
	},
	[102010] = {
		id = 102010,
		fmt = "#C0xF76B45#【Gym Log】",
		fmt_th = "#C0xF76B45#【บันทึกยิม】",
		fmt_en = "#C0xF76B45#【Gym Log】"
	},
