		fmt_th = "1. เฉพาะ #C0xF76B45#ประวัติการท้าทาย PvP ส่วนตัว#C0x5B545B#และ #C0xF76B45#ประวัติการเคลียร์ดันเจี้ยนยิมจะถูกบันทึกไว้ในบันทึกยิม",
