		fmt = "3. Boost Points will increase by a small amount every day at 5am. It is also available from purchasing with Diamonds or cleaning Gym.",
		fmt_th = "3. Boost Points จะเพิ่มขึ้นเล็กน้อยทุกวันตอนตี 5 นอกจากนี้ยังสามารถซื้อได้ที่  Diamond s หรือทำความสะอาดยิม",
