	[106002] = {
		id = 106002,
		fmt = "2. Different shard has different convertible amount and limit.",
		fmt_th = "2. ชาร์ดที่ต่างกันมีจำนวนและขีดจำกัดที่เปลี่ยนแปลงได้ต่างกัน",
