	},
	[106003] = {
		id = 106003,
		fmt = "3. The higher the VIP level, the more chances to convert.",
		fmt_th = "3. ยิ่งระดับ  VIP สูงเท่าใด โอกาสในการแปลงก็จะมากขึ้นเท่านั้น",
