		fmt_th = "1. สะสมชั้นเคลียร์ (ท้าทายบอสสุดท้ายของแต่ละชั้น) ที่  Aether Paradise ทุกวันเพื่อปลดล็อกรางวัลผ่านอย่างใจกว้าง",
