	[124701] = {
		id = 124701,
		fmt = "1. Enhancement can improve chip level, the higher the level, the higher the main attribute",
		fmt_th = "1. การเพิ่มประสิทธิภาพสามารถปรับปรุงระดับชิปได้ ยิ่งระดับสูงเท่าใด คุณสมบัติหลักก็จะยิ่งสูงขึ้น",
