		fmt = "3. Special tips is hidden in the conversations of stages. After stage clear, you can view the plot review on the information interface",
		fmt_th = "3. เคล็ดลับพิเศษซ่อนอยู่ในบทสนทนาของด่าน หลังจากเคลียร์ด่านแล้ว คุณสามารถดูการทบทวนพล็อตได้ที่อินเทอร์เฟซข้อมูล",
