	[125301] = {
		id = 125301,
		fmt = "1. During the event, you can pray on the event interface after completing the task.",
		fmt_th = "1. ในระหว่างกิจกรรม คุณสามารถอธิษฐานที่หน้าจอกิจกรรมได้หลังจากเสร็จสิ้นภารกิจ",
		fmt_en = "1. During the event, you can pray on the event interface after completing the task."
	},
	[125302] = {
		id = 125302,
		fmt = "2. When praying, you can get random ordinary blessings, and you can also get lucky blessings",
		fmt_th = "2. เมื่อสวดมนต์ จะได้รับพรธรรมดาแบบสุ่ม และยังสามารถรับพรนำโชคได้อีกด้วย",
		fmt_en = "2. When praying, you can get random ordinary blessings, and you can also get lucky blessings"
	},
	[125303] = {
		id = 125303,
		fmt = "3. Every time you pray, if you don't get lucky blessings, you will be able to light up a lucky sign. The more lucky signs are lit, the higher the probability of getting lucky blessings. When you light up all the lucky signs in the interface , the next time you will definitely get lucky blessings",
		fmt_th = "3. ทุกครั้งที่สวดมนต์ ถ้าไม่ได้รับพร จะสามารถจุดไฟได้ ยิ่งมีไฟสัญญาณนำโชคมากเท่าใด โอกาสที่จะได้รับคำอวยพรก็จะยิ่งสูงขึ้นเท่านั้น เมื่อคุณทำให้สัญญาณนำโชคทั้งหมดสว่างขึ้นในอินเทอร์เฟซ ครั้งต่อไปคุณจะได้รับพรอย่างแน่นอน",
		fmt_en = "3. Every time you pray, if you don't get lucky blessings, you will be able to light up a lucky sign. The more lucky signs are lit, the higher the probability of getting lucky blessings. When you light up all the lucky signs in the interface , the next time you will definitely get lucky blessings"
	},
	[125304] = {
		id = 125304,
		fmt = "4. The task is reset regularly every day. Please pay attention to completing and claiming it in time. The number of blessings you have obtained will not be reset and will remain until the end of the event.",
		fmt_th = "4. งานจะถูกรีเซ็ตเป็นประจำทุกวัน โปรดใส่ใจในการกรอกและอ้างสิทธิ์ให้ทันเวลา จำนวนพรที่คุณได้รับจะไม่ถูกรีเซ็ตและจะคงอยู่จนกว่าจะสิ้นสุดกิจกรรม",
		fmt_en = "4. The task is reset regularly every day. Please pay attention to completing and claiming it in time. The number of blessings you have obtained will not be reset and will remain until the end of the event."
	},
	[125305] = {
		id = 125305,
		fmt = "5. In the prayer record in the prayer task interface, you can view the reward content obtained in this event",
		fmt_th = "5. ในบันทึกคำอธิษฐานในอินเทอร์เฟซงานสวดมนต์ คุณสามารถดูเนื้อหารางวัลที่ได้รับในกิจกรรมนี้",
		fmt_en = "5. In the prayer record in the prayer task interface, you can view the reward content obtained in this event"
	},
	[125401] = {
		id = 125401,
		fmt = "1. The maximum number of emails is #C0xF76B45#60#C0x5B545B#",
		fmt_th = "1. จำนวนอีเมลสูงสุดคือ #C0xF76B45#60#C0x5B545B#",
		fmt_en = "1. The maximum number of emails is #C0xF76B45#60#C0x5B545B#"
	},
	[125402] = {
		id = 125402,
		fmt = "2. When the email limit is exceeded, some old emails will be lost, please deal with them in time",
		fmt_th = "2. เมื่อเกินขีดจำกัดอีเมล อีเมลเก่าบางฉบับจะสูญหาย โปรดจัดการกับมันให้ทันเวลา",
		fmt_en = "2. When the email limit is exceeded, some old emails will be lost, please deal with them in time"
