	[125501] = {
		id = 125501,
		fmt = "#L10##C0xF76B45# Powerhouses, welcome to the big battle",
		fmt_th = "#L10##C0xF76B45# ขุมพลัง ยินดีต้อนรับสู่ศึกใหญ่",
		fmt_en = "#L10##C0xF76B45# Powerhouses, welcome to the big battle"
	},
	[125502] = {
		id = 125502,
		fmt = "#L10##C0xF76B45#【Selection Rules】",
		fmt_th = "#L10##C0xF76B45#【กฎการเลือก】",
		fmt_en = "#L10##C0xF76B45#【Selection Rules】"
	},
	[125503] = {
		id = 125503,
		fmt = "1. The Ministry of Housing project requires a total of #C0xF76B45#16#C0x5B545B# strong guilds to compete in multiple servers.",
		fmt_th = "1. โครงการกระทรวงการเคหะต้องการกิลด์ที่แข็งแกร่ง #C0xF76B45#16#C0x5B545B# กิลด์ที่แข็งแกร่งเพื่อแข่งขันในหลายเซิร์ฟเวอร์",
		fmt_en = "1. The Ministry of Housing project requires a total of #C0xF76B45#16#C0x5B545B# strong guilds to compete in multiple servers."
	},
	[125504] = {
		id = 125504,
		fmt = "2. The project will be selected based on the accumulated points of the three-week guild battle (can be viewed in the battle interface of the Ministry), and the guilds ranked #C0xF76B45# first and second #C0x5B545B# will be selected directly",
		fmt_th = "2. โปรเจ็กต์จะถูกเลือกตามคะแนนสะสมของการต่อสู้กิลด์สามสัปดาห์ (สามารถดูได้ในอินเทอร์เฟซการต่อสู้ของกระทรวง) และกิลด์อันดับ #C0xF76B45# ที่หนึ่งและที่สอง #C0x5B545B# จะถูกเลือกโดยตรง",
		fmt_en = "2. The project will be selected based on the accumulated points of the three-week guild battle (can be viewed in the battle interface of the Ministry), and the guilds ranked #C0xF76B45# first and second #C0x5B545B# will be selected directly"
	},
	[125505] = {
		id = 125505,
		fmt = "3. If the guilds in the matching cross-server group cannot gather the required number of projects, they will be selected according to the 3-5 guilds in the same cross-server group with the guild battle points ranking (the guild with the higher total combat power will be selected first. )",
		fmt_th = "3. หากกิลด์ในกลุ่มข้ามเซิร์ฟเวอร์ที่ตรงกันไม่สามารถรวบรวมจำนวนโครงการที่ต้องการได้ พวกเขาจะถูกเลือกตาม 3-5 กิลด์ในกลุ่มข้ามเซิร์ฟเวอร์เดียวกันกับอันดับคะแนนการต่อสู้ของกิลด์ (กิลด์ที่มีอันดับสูงกว่า พลังต่อสู้ทั้งหมดจะถูกเลือกก่อน )",
		fmt_en = "3. If the guilds in the matching cross-server group cannot gather the required number of projects, they will be selected according to the 3-5 guilds in the same cross-server group with the guild battle points ranking (the guild with the higher total combat power will be selected first. )"
	},
	[125506] = {
		id = 125506,
		fmt = "4. After the three-week guild battle is over, the guild and the members participating in the guild will be locked, and the members who join the selected guild in the future will not be able to participate in the current Ministry of War.",
		fmt_th = "4. หลังจากการต่อสู้กิลด์สามสัปดาห์สิ้นสุดลง กิลด์และสมาชิกที่เข้าร่วมในกิลด์จะถูกล็อค และสมาชิกที่เข้าร่วมกิลด์ที่เลือกในอนาคตจะไม่สามารถเข้าร่วมในกระทรวงสงครามปัจจุบันได้",
		fmt_en = "4. After the three-week guild battle is over, the guild and the members participating in the guild will be locked, and the members who join the selected guild in the future will not be able to participate in the current Ministry of War."
	},
	[125507] = {
		id = 125507,
		fmt = "#L10##C0xF76B45#【Basic Rules】",
		fmt_th = "#L10##C0xF76B45#【กฎพื้นฐาน】",
		fmt_en = "#L10##C0xF76B45#【Basic Rules】"
	},
	[125508] = {
		id = 125508,
		fmt = "1. The Battle of the House is based on #C0xF76B45# for four weeks and #C0x5B545B# as a season. After collecting the guild battle points ranking information for three weeks, the fourth week will start.",
		fmt_th = "1. Battle of the House อิงจาก #C0xF76B45# เป็นเวลาสี่สัปดาห์และ #C0x5B545B# ต่อฤดูกาล หลังจากรวบรวมข้อมูลอันดับคะแนนการต่อสู้กิลด์เป็นเวลาสามสัปดาห์ สัปดาห์ที่สี่จะเริ่มขึ้น",
		fmt_en = "1. The Battle of the House is based on #C0xF76B45# for four weeks and #C0x5B545B# as a season. After collecting the guild battle points ranking information for three weeks, the fourth week will start."
	},
	[125509] = {
		id = 125509,
		fmt = "2. The Battle of the Household is divided into two stages: the preliminary round and the final round. The preliminary round is the #C0xF76B45# Friday #C0x5B545B# of the opening week, and the final is the #C0xF76B45# Sunday #C0x5B545B# of the opening week.",
		fmt_th = "2. การต่อสู้ของครัวเรือนแบ่งออกเป็นสองขั้นตอน: รอบเบื้องต้นและรอบสุดท้าย รอบเบื้องต้นคือ #C0xF76B45# วันศุกร์ #C0x5B545B# ของสัปดาห์เปิด และรอบสุดท้ายคือ #C0xF76B45# วันอาทิตย์ #C0x5B545B# ของสัปดาห์เปิด",
		fmt_en = "2. The Battle of the Household is divided into two stages: the preliminary round and the final round. The preliminary round is the #C0xF76B45# Friday #C0x5B545B# of the opening week, and the final is the #C0xF76B45# Sunday #C0x5B545B# of the opening week."
	},
	[125510] = {
		id = 125510,
		fmt = "3. For the selected guild, the system will automatically register the guild members. The members in the guild need to choose their own engineering team and corresponding lineup in #C0xF76B45#9:00~20:50#C0x5B545B#",
		fmt_th = "3. สำหรับกิลด์ที่เลือก ระบบจะลงทะเบียนสมาชิกกิลด์โดยอัตโนมัติ สมาชิกในกิลด์ต้องเลือกทีมวิศวกรของตัวเองและรายชื่อผู้เล่นที่เกี่ยวข้องใน #C0xF76B45#9:00~20:50#C0x5B545B#",
		fmt_en = "3. For the selected guild, the system will automatically register the guild members. The members in the guild need to choose their own engineering team and corresponding lineup in #C0xF76B45#9:00~20:50#C0x5B545B#"
	},
	[125511] = {
		id = 125511,
		fmt = "4. For players who do not select a battlefield 10 minutes before the game, the system will randomly assign the battlefield and select the elves with higher combat power.",
		fmt_th = "4. สำหรับผู้เล่นที่ไม่ได้เลือกสนามรบก่อนเกม 10 นาที ระบบจะสุ่มกำหนดสนามรบและเลือกเอลฟ์ที่มีพลังต่อสู้สูงกว่า",
		fmt_en = "4. For players who do not select a battlefield 10 minutes before the game, the system will randomly assign the battlefield and select the elves with higher combat power."
	},
	[125512] = {
		id = 125512,
		fmt = "5. Official start time: #C0xF76B45#21:00#C0x5B545B#",
		fmt_th = "5. เวลาเริ่มต้นอย่างเป็นทางการ: #C0xF76B45#21:00#C0x5B545B#",
		fmt_en = "5. Official start time: #C0xF76B45#21:00#C0x5B545B#"
	},
	[125513] = {
		id = 125513,
		fmt = "#L10##C0xF76B45#【Preliminary Rules】",
		fmt_th = "#L10##C0xF76B45#【กฎเบื้องต้น】",
		fmt_en = "#L10##C0xF76B45#【Preliminary Rules】"
	},
	[125514] = {
		id = 125514,
		fmt = "1. Preliminary stage: The 16 guilds selected are divided into four bidding groups according to their combat power rankings. Members of the guild need to register for the engineering group they want to participate in within the specified time.",
		fmt_th = "1. ขั้นตอนเบื้องต้น: กิลด์ทั้ง 16 กิลด์ที่ถูกเลือกจะถูกแบ่งออกเป็นกลุ่มประมูลสี่กลุ่มตามอันดับอำนาจการต่อสู้ของพวกเขา สมาชิกของกิลด์ต้องลงทะเบียนสำหรับกลุ่มวิศวกรรมที่ต้องการเข้าร่วมภายในเวลาที่กำหนด",
		fmt_en = "1. Preliminary stage: The 16 guilds selected are divided into four bidding groups according to their combat power rankings. Members of the guild need to register for the engineering group they want to participate in within the specified time."
	},
	[125515] = {
		id = 125515,
		fmt = "2. There are three types of engineering groups",
		fmt_th = "2. กลุ่มวิศวกรรมมี 3 ประเภท",
		fmt_en = "2. There are three types of engineering groups"
	},
	[125516] = {
		id = 125516,
		fmt = "   6-person construction group: two teams can be dispatched, each with 6 elves",
		fmt_th = "กลุ่มก่อสร้าง 6 คน: สามารถส่งได้สองทีม โดยแต่ละทีมมี 6 เอลฟ์",
		fmt_en = "   6-person construction group: two teams can be dispatched, each with 6 elves"
	},
	[125517] = {
		id = 125517,
		fmt = "   4-person survey team: Three teams can be dispatched, with 4 elves in each team",
		fmt_th = "ทีมสำรวจ 4 คน: สามารถส่งได้สามทีม โดยมี 4 เอลฟ์ในแต่ละทีม",
		fmt_en = "   4-person survey team: Three teams can be dispatched, with 4 elves in each team"
	},
	[125518] = {
		id = 125518,
		fmt = "   1-person design team: 3 teams can be dispatched, each team has 3 elves",
		fmt_th = "ทีมออกแบบ 1 คน: ส่งได้ 3 ทีม แต่ละทีมมี 3 เอลฟ์",
		fmt_en = "   1-person design team: 3 teams can be dispatched, each team has 3 elves"
	},
	[125519] = {
		id = 125519,
		fmt = "Participating players can only choose one of the arenas to participate in the battle. After the registration period ends, the engineering team and the battle elves will be locked, and cannot be modified after the battle starts.",
		fmt_th = "ผู้เล่นที่เข้าร่วมสามารถเลือกหนึ่งในอารีน่าเพื่อเข้าร่วมการต่อสู้เท่านั้น หลังจากสิ้นสุดระยะเวลาการลงทะเบียน ทีมวิศวกรและแบทเทิลเอลฟ์จะถูกล็อค และไม่สามารถแก้ไขได้หลังจากการต่อสู้เริ่มต้นขึ้น",
		fmt_en = "Participating players can only choose one of the arenas to participate in the battle. After the registration period ends, the engineering team and the battle elves will be locked, and cannot be modified after the battle starts."
	},
	[125520] = {
		id = 125520,
		fmt = "3. During the battle, after the first team is knocked down, the second team can continue to fight in the next round",
		fmt_th = "3. ระหว่างการต่อสู้ หลังจากที่ทีมแรกล้มลง ทีมที่สองสามารถสู้ต่อไปได้ในรอบต่อไป",
		fmt_en = "3. During the battle, after the first team is knocked down, the second team can continue to fight in the next round"
	},
	[125521] = {
		id = 125521,
		fmt = "4. The form of the competition is the melee mode, and you will be matched with non-guild players first (when the remaining players are all members of the guild, the battle will end)",
		fmt_th = "4. รูปแบบของการแข่งขันคือโหมดระยะประชิด และคุณจะจับคู่กับผู้เล่นที่ไม่ใช่กิลด์ก่อน (เมื่อผู้เล่นที่เหลือเป็นสมาชิกทั้งหมดของกิลด์ การต่อสู้จะสิ้นสุดลง)",
		fmt_en = "4. The form of the competition is the melee mode, and you will be matched with non-guild players first (when the remaining players are all members of the guild, the battle will end)"
	},
	[125522] = {
		id = 125522,
		fmt = "5. The victorious player can continue the next round of battle and continue to fight against other non-guild opponents",
		fmt_th = "5. ผู้เล่นที่ได้รับชัยชนะสามารถดำเนินการต่อในรอบต่อไปของการต่อสู้และต่อสู้กับฝ่ายตรงข้ามที่ไม่ใช่กิลด์อื่น ๆ ต่อไป",
		fmt_en = "5. The victorious player can continue the next round of battle and continue to fight against other non-guild opponents"
	},
	[125523] = {
		id = 125523,
		fmt = "6. Players who have no elves to play will be temporarily eliminated. If the guild of the eliminated player successfully advances to the finals, they will advance together; if the guild to which they belong fails to advance, they will not be able to compete for the championship.",
		fmt_th = "6. ผู้เล่นที่ไม่มีเอลฟ์เล่นจะถูกคัดออกชั่วคราว หากกิลด์ของผู้เล่นที่ถูกคัดออกสามารถผ่านเข้าสู่รอบชิงชนะเลิศได้สำเร็จ พวกเขาจะผ่านเข้าไปพร้อมกัน หากกิลด์ที่พวกเขาอยู่ไม่สามารถก้าวไปข้างหน้าได้ พวกเขาก็จะไม่สามารถแข่งขันเพื่อชิงแชมป์ได้",
		fmt_en = "6. Players who have no elves to play will be temporarily eliminated. If the guild of the eliminated player successfully advances to the finals, they will advance together; if the guild to which they belong fails to advance, they will not be able to compete for the championship."
	},
	[125524] = {
		id = 125524,
		fmt = "6. Retain health and rage after each battle",
		fmt_th = "6. รักษาสุขภาพและความโกรธหลังจากการต่อสู้แต่ละครั้ง",
