	[125530] = {
		id = 125530,
		fmt = "9. Whether a guild is promoted or not is determined by the aggregated points of the guild members in different engineering groups on that day",
		fmt_th = "9. กิลด์จะได้รับการเลื่อนตำแหน่งหรือไม่นั้นพิจารณาจากคะแนนรวมของสมาชิกกิลด์ในกลุ่มวิศวกรรมต่างๆ ในวันนั้น",
