	[125531] = {
		id = 125531,
		fmt = "10. The two sides will fight for a maximum of 10 rounds. If there is no winner or loser at the end of the time, the side with the most remaining HP will win.",
		fmt_th = "10. ทั้งสองฝ่ายจะต่อสู้กันไม่เกิน 10 รอบ หากไม่มีผู้ชนะหรือผู้แพ้เมื่อสิ้นสุดเวลา ฝ่ายที่มี HP ที่เหลืออยู่มากที่สุดจะเป็นผู้ชนะ",
		fmt_en = "10. The two sides will fight for a maximum of 10 rounds. If there is no winner or loser at the end of the time, the side with the most remaining HP will win."
	},
	[125532] = {
		id = 125532,
		fmt = "11. After the preliminary round, the four battle groups will select their first teams to participate in the finals, and the remaining guilds will be eliminated.",
