	[125539] = {
		id = 125539,
		fmt = "1. During the entire battle of the Big House, in each round of the battle, all elves who enter the battle team for the first time can get certain attribute bonuses such as attack, defense, speed, etc.",
		fmt_th = "1. ระหว่างการต่อสู้ในบ้านหลังใหญ่ ในแต่ละรอบของการต่อสู้ เอลฟ์ทุกคนที่เข้าร่วมทีมต่อสู้เป็นครั้งแรกจะได้รับโบนัสคุณสมบัติบางอย่าง เช่น การโจมตี การป้องกัน ความเร็ว ฯลฯ",
		fmt_en = "1. During the entire battle of the Big House, in each round of the battle, all elves who enter the battle team for the first time can get certain attribute bonuses such as attack, defense, speed, etc."
	},
	[125540] = {
		id = 125540,
		fmt = "2. As the battle continues, the bonus of this attribute will be attenuated, and the elves will become exhausted, and the fighting ability will become weaker and weaker.",
		fmt_th = "2. ในขณะที่การต่อสู้ดำเนินต่อไป โบนัสของคุณลักษณะนี้จะถูกลดทอนลง และเอลฟ์จะหมดแรง และความสามารถในการต่อสู้จะอ่อนแอลงเรื่อยๆ",
		fmt_en = "2. As the battle continues, the bonus of this attribute will be attenuated, and the elves will become exhausted, and the fighting ability will become weaker and weaker."
	},
	[125541] = {
		id = 125541,
		fmt = "3. Every time you participate in a battle after that, the attributes of the elves in the team, such as attack, defense, speed, and healing amount, will continue to decrease.",
		fmt_th = "3. ทุกครั้งที่คุณเข้าร่วมการต่อสู้หลังจากนั้น คุณสมบัติของเอลฟ์ในทีม เช่น การโจมตี การป้องกัน ความเร็ว และจำนวนการรักษา จะลดลงอย่างต่อเนื่อง",
		fmt_en = "3. Every time you participate in a battle after that, the attributes of the elves in the team, such as attack, defense, speed, and healing amount, will continue to decrease."
	},
