	[128601] = {
		id = 128601,
		fmt = "#C0xF76B45#【Small game rules】",
		fmt_th = "#C0xF76B45#【Small game rules】",
		fmt_en = "#C0xF76B45#【Small game rules】"
	},
	[128602] = {
		id = 128602,
		fmt = "1.Each player calculates the point value of their own cards in the game with Mr. Mime. The one whose point value is closest to 21 without exceeding it, #C0xF76B45# wins the game!",
		fmt_th = "1.Each player calculates the point value of their own cards in the game with Mr. Mime. The one whose point value is closest to 21 without exceeding it, #C0xF76B45# wins the game!",
		fmt_en = "1.Each player calculates the point value of their own cards in the game with Mr. Mime. The one whose point value is closest to 21 without exceeding it, #C0xF76B45# wins the game!"
	},
	[128603] = {
		id = 128603,
		fmt = "2. Each game can be used: #C0xF76B45# 4 cards with 2-9 points each, 16 cards with 10 points, and 4 variable cards with flexible changes of 1 or 11 points. When cards 2-9 are drawn, the points will be calculated according to the displayed numbers, and when Ditto is drawn to, 1 or 11 points can be flexibly substituted into the calculation",
		fmt_th = "2. Each game can be used: #C0xF76B45# 4 cards with 2-9 points each, 16 cards with 10 points, and 4 variable cards with flexible changes of 1 or 11 points. When cards 2-9 are drawn, the points will be calculated according to the displayed numbers, and when Ditto is drawn to, 1 or 11 points can be flexibly substituted into the calculation",
		fmt_en = "2. Each game can be used: #C0xF76B45# 4 cards with 2-9 points each, 16 cards with 10 points, and 4 variable cards with flexible changes of 1 or 11 points. When cards 2-9 are drawn, the points will be calculated according to the displayed numbers, and when Ditto is drawn to, 1 or 11 points can be flexibly substituted into the calculation"
	},
	[128604] = {
		id = 128604,
		fmt = "3.After the game starts, Mr. Mime will perform a card dealing show, and each person will receive 2 initial cards. The last initial card obtained by Mr. Mime will be turned over and its point value cannot be seen.",
		fmt_th = "3.After the game starts, Mr. Mime will perform a card dealing show, and each person will receive 2 initial cards. The last initial card obtained by Mr. Mime will be turned over and its point value cannot be seen.",
		fmt_en = "3.After the game starts, Mr. Mime will perform a card dealing show, and each person will receive 2 initial cards. The last initial card obtained by Mr. Mime will be turned over and its point value cannot be seen."
	},
	[128605] = {
		id = 128605,
		fmt = "4. Next #C0xF76B45# will be operated by you first, #C0x5B545B# After you confirm the operation is over, Mr. Mime will operate again",
		fmt_th = "4. Next #C0xF76B45# will be operated by you first, #C0x5B545B# After you confirm the operation is over, Mr. Mime will operate again",
		fmt_en = "4. Next #C0xF76B45# will be operated by you first, #C0x5B545B# After you confirm the operation is over, Mr. Mime will operate again"
	},
	[128606] = {
		id = 128606,
		fmt = "5.You can perform 2 basic operations on cards: #C0xF76B45# ask for cards, stop cards. #C0x5B545B#You can #C0xF76B45#Continuously ask for cards, #C0x5B545B#But #C0xF76B45#When you click on the suspension #C0x5B545B#, #C0xF76B45#Your operations in this game will all end, #C0x5B545B#Next wait for Mr. Mime to operate After the point comparison settlement",
		fmt_th = "5.You can perform 2 basic operations on cards: #C0xF76B45# ask for cards, stop cards. #C0x5B545B#You can #C0xF76B45#Continuously ask for cards, #C0x5B545B#But #C0xF76B45#When you click on the suspension #C0x5B545B#, #C0xF76B45#Your operations in this game will all end, #C0x5B545B#Next wait for Mr. Mime to operate After the point comparison settlement",
		fmt_en = "5.You can perform 2 basic operations on cards: #C0xF76B45# ask for cards, stop cards. #C0x5B545B#You can #C0xF76B45#Continuously ask for cards, #C0x5B545B#But #C0xF76B45#When you click on the suspension #C0x5B545B#, #C0xF76B45#Your operations in this game will all end, #C0x5B545B#Next wait for Mr. Mime to operate After the point comparison settlement"
	},
	[128607] = {
		id = 128607,
		fmt = "6. After each card is asked, the point value will be automatically calculated according to the current card face of #C0xF76B45#, #C0x5B545B# Note #C0xF76B45# If any party #C0x5B545B#'s card face point calculation #C0xF76B45# all results exceed 21 points, #C0x5B545B#Then #C0xF76B45# will automatically stop asking for cards, and will be sentenced to lose; #C0x5B545B# If you are ruled to lose when you go first, the game is over",
		fmt_th = "6. After each card is asked, the point value will be automatically calculated according to the current card face of #C0xF76B45#, #C0x5B545B# Note #C0xF76B45# If any party #C0x5B545B#'s card face point calculation #C0xF76B45# all results exceed 21 points, #C0x5B545B#Then #C0xF76B45# will automatically stop asking for cards, and will be sentenced to lose; #C0x5B545B# If you are ruled to lose when you go first, the game is over",
		fmt_en = "6. After each card is asked, the point value will be automatically calculated according to the current card face of #C0xF76B45#, #C0x5B545B# Note #C0xF76B45# If any party #C0x5B545B#'s card face point calculation #C0xF76B45# all results exceed 21 points, #C0x5B545B#Then #C0xF76B45# will automatically stop asking for cards, and will be sentenced to lose; #C0x5B545B# If you are ruled to lose when you go first, the game is over"
	},
	[128608] = {
		id = 128608,
		fmt = "7. If both parties have suspended trading, and #C0xF76B45# both sides have any board point calculation result not exceeding 21, #C0x5B545B#, the two sides will #C0xF76B45# compare the size, and the one with the larger point value wins; #C0x5B545B# If #C0xF76B45# both sides have the same points, #C0x5B545B# will still judge #C0xF76B45# Mr. Mime to win",
		fmt_th = "7. If both parties have suspended trading, and #C0xF76B45# both sides have any board point calculation result not exceeding 21, #C0x5B545B#, the two sides will #C0xF76B45# compare the size, and the one with the larger point value wins; #C0x5B545B# If #C0xF76B45# both sides have the same points, #C0x5B545B# will still judge #C0xF76B45# Mr. Mime to win",
		fmt_en = "7. If both parties have suspended trading, and #C0xF76B45# both sides have any board point calculation result not exceeding 21, #C0x5B545B#, the two sides will #C0xF76B45# compare the size, and the one with the larger point value wins; #C0x5B545B# If #C0xF76B45# both sides have the same points, #C0x5B545B# will still judge #C0xF76B45# Mr. Mime to win"
