		fmt_en = "1.After the game starts, there are a total of#C0xF76B45# 5 dart throwing opportunities#C0x5B545B#. Players need to #C0xF76B45#use 5 darts to clear the initial target score of 204 points#C0x5B545B#. The right-hand score board in the game interface will record in detail the player's score and the current score difference for each dart thrown. Be sure to check it out."
