	[129007] = {
		id = 129007,
		fmt = "3. In the game, if the score of shooting darts #C0xF76B45# is higher than 204 points #C0x5B545B#, it will be regarded as #C0xF76B45#Exploding dart#C0x5B545B#, and #C0xF76B45# will cancel the current throwing score #C0x5B545B#, if #C0xF76B45#There is still a chance to shoot darts #C0x5B545B#, then #C0xF76B45# will continue the game, after shooting 5 darts, the game will be settled #C0x5B545B#, give an evaluation based on the current point difference and get rewards",
		fmt_th = "3. In the game, if the score of shooting darts #C0xF76B45# is higher than 204 points #C0x5B545B#, it will be regarded as #C0xF76B45#Exploding dart#C0x5B545B#, and #C0xF76B45# will cancel the current throwing score #C0x5B545B#, if #C0xF76B45#There is still a chance to shoot darts #C0x5B545B#, then #C0xF76B45# will continue the game, after shooting 5 darts, the game will be settled #C0x5B545B#, give an evaluation based on the current point difference and get rewards",
