	[132201] = {
		id = 132201,
		fmt = "Every #C0xF76B45#4#C0x5B545B#minute random #C0xF76B45#3#C0x5B545B# stronghold area (except the camp), the current team of the player in the stronghold will deduct #C0xF76B45#60%#C0x5B545B# HP, the player in the battle won't be hurt",
