	},
	[132301] = {
		id = 132301,
		fmt = "The top and bottom four paths of this theme are fixed fast lanes (with acceleration signs). Walking on the paths can increase the movement speed of #C0xF76B45#80%#C0x5B545B#.",
		fmt_th = "The top and bottom four paths of this theme are fixed fast lanes (with acceleration signs). Walking on the paths can increase the movement speed of #C0xF76B45#80%#C0x5B545B#.",
		fmt_en = "The top and bottom four paths of this theme are fixed fast lanes (with acceleration signs). Walking on the paths can increase the movement speed of #C0xF76B45#80%#C0x5B545B#."
	},
	[132302] = {
		id = 132302,
		fmt = "The theme effect is once every #C0xF76B45#4#C0x5B545B# minutes. A random #C0xF76B45#3#C0x5B545B# road generates turbulent water. The movement speed of walking along the current is increased by #C0xF76B45#100%#C0x5B545B#, and the movement speed of walking against the water is slowed down# C0xF76B45#50%#C0x5B545B#, Turbulent Water lasts #C0xF76B45#30#C0x5B545B# seconds",
		fmt_th = "The theme effect is once every #C0xF76B45#4#C0x5B545B# minutes. A random #C0xF76B45#3#C0x5B545B# road generates turbulent water. The movement speed of walking along the current is increased by #C0xF76B45#100%#C0x5B545B#, and the movement speed of walking against the water is slowed down# C0xF76B45#50%#C0x5B545B#, Turbulent Water lasts #C0xF76B45#30#C0x5B545B# seconds",
		fmt_en = "The theme effect is once every #C0xF76B45#4#C0x5B545B# minutes. A random #C0xF76B45#3#C0x5B545B# road generates turbulent water. The movement speed of walking along the current is increased by #C0xF76B45#100%#C0x5B545B#, and the movement speed of walking against the water is slowed down# C0xF76B45#50%#C0x5B545B#, Turbulent Water lasts #C0xF76B45#30#C0x5B545B# seconds"
	},
	[132401] = {
		id = 132401,
		fmt = "Incendiary Blaze: Every #C0xF76B45#4#C0x5B545B# minutes, two incendiary fireballs will randomly spawn from #C0xF76B45#2#C0x5B545B# different locations. These two incendiary fireballs will move along the path, choosing neighboring locations at random after reaching the next adjacent point. Players from the current team run over by the fireballs will have #C0xF76B45#40%#C0x5B545B# of their health deducted, and the fireballs will dissipate after #C0xF76B45#35#C0x5B545B# seconds.",
		fmt_th = "Incendiary Blaze: Every #C0xF76B45#4#C0x5B545B# minutes, two incendiary fireballs will randomly spawn from #C0xF76B45#2#C0x5B545B# different locations. These two incendiary fireballs will move along the path, choosing neighboring locations at random after reaching the next adjacent point. Players from the current team run over by the fireballs will have #C0xF76B45#40%#C0x5B545B# of their health deducted, and the fireballs will dissipate after #C0xF76B45#35#C0x5B545B# seconds.",
		fmt_en = "Incendiary Blaze: Every #C0xF76B45#4#C0x5B545B# minutes, two incendiary fireballs will randomly spawn from #C0xF76B45#2#C0x5B545B# different locations. These two incendiary fireballs will move along the path, choosing neighboring locations at random after reaching the next adjacent point. Players from the current team run over by the fireballs will have #C0xF76B45#40%#C0x5B545B# of their health deducted, and the fireballs will dissipate after #C0xF76B45#35#C0x5B545B# seconds."
	},
	[132501] = {
		id = 132501,
		fmt = "The Final Frost: Every #C0xF76B45#4#C0x5B545B# minutes, the battlefield experiences an intense cold snap, freezing players on the path for #C0xF76B45#30#C0x5B545B# seconds. During this frozen period, they cannot move or engage in combat. Players stationed within strongholds and those currently battling on the path will not be affected by the intense cold snap.",
		fmt_th = "The Final Frost: Every #C0xF76B45#4#C0x5B545B# minutes, the battlefield experiences an intense cold snap, freezing players on the path for #C0xF76B45#30#C0x5B545B# seconds. During this frozen period, they cannot move or engage in combat. Players stationed within strongholds and those currently battling on the path will not be affected by the intense cold snap.",
		fmt_en = "The Final Frost: Every #C0xF76B45#4#C0x5B545B# minutes, the battlefield experiences an intense cold snap, freezing players on the path for #C0xF76B45#30#C0x5B545B# seconds. During this frozen period, they cannot move or engage in combat. Players stationed within strongholds and those currently battling on the path will not be affected by the intense cold snap."
	},
	[132601] = {
		id = 132601,
		fmt = "Spectral Revenants: Every #C0xF76B45#4#C0x5B545B# minutes, spectral revenants will assault all individuals on the field. They will deduct #C0xF76B45#0.07%#C0x5B545B# of the current team's total health based on the number of casualties indicated at the time of the assault prompt.",
		fmt_th = "Spectral Revenants: Every #C0xF76B45#4#C0x5B545B# minutes, spectral revenants will assault all individuals on the field. They will deduct #C0xF76B45#0.07%#C0x5B545B# of the current team's total health based on the number of casualties indicated at the time of the assault prompt.",
		fmt_en = "Spectral Revenants: Every #C0xF76B45#4#C0x5B545B# minutes, spectral revenants will assault all individuals on the field. They will deduct #C0xF76B45#0.07%#C0x5B545B# of the current team's total health based on the number of casualties indicated at the time of the assault prompt."
