	[135301] = {
		id = 135301,
		fmt = "Make a contract with the Pokémon to make it stronger",
		fmt_th = "Make a contract with the Pokémon to make it stronger",
		fmt_en = "Make a contract with the Pokémon to make it stronger"
	},
	[135302] = {
		id = 135302,
		fmt = "#L10##C0xF76B45#【Contract Introduction】",
		fmt_th = "#L10##C0xF76B45#【Contract Introduction】",
		fmt_en = "#L10##C0xF76B45#【Contract Introduction】"
	},
	[135303] = {
		id = 135303,
		fmt = "1. Contracts have different qualities and types, which can bring attributes and various bonuses in combat.",
		fmt_th = "1. Contracts have different qualities and types, which can bring attributes and various bonuses in combat.",
		fmt_en = "1. Contracts have different qualities and types, which can bring attributes and various bonuses in combat."
	},
	[135304] = {
		id = 135304,
		fmt = "2. The contract can be upgraded. Each time you upgrade to a fixed level, you need to make a breakthrough to expand the level of the next stage before upgrading.",
		fmt_th = "2. The contract can be upgraded. Each time you upgrade to a fixed level, you need to make a breakthrough to expand the level of the next stage before upgrading.",
		fmt_en = "2. The contract can be upgraded. Each time you upgrade to a fixed level, you need to make a breakthrough to expand the level of the next stage before upgrading."
	},
	[135305] = {
		id = 135305,
		fmt = "3. Contracts can be reborn. #C0xF76B45# Contracts obtained in the interface-acquisition portal cannot be broken down or used as materials for upgrading and breakthrough of other contracts.",
		fmt_th = "3. Contracts can be reborn. #C0xF76B45# Contracts obtained in the interface-acquisition portal cannot be broken down or used as materials for upgrading and breakthrough of other contracts.",
		fmt_en = "3. Contracts can be reborn. #C0xF76B45# Contracts obtained in the interface-acquisition portal cannot be broken down or used as materials for upgrading and breakthrough of other contracts."
	},
	[135306] = {
		id = 135306,
		fmt = "4.#C0xF76B45# Some contracts can trigger bonds. That is, after being assembled on the same Pokémon, the bond effect will take effect, which can bring additional effects to the Pokémon.",
		fmt_th = "4.#C0xF76B45# Some contracts can trigger bonds. That is, after being assembled on the same Pokémon, the bond effect will take effect, which can bring additional effects to the Pokémon.",
		fmt_en = "4.#C0xF76B45# Some contracts can trigger bonds. That is, after being assembled on the same Pokémon, the bond effect will take effect, which can bring additional effects to the Pokémon."
	},
	[135307] = {
		id = 135307,
		fmt = "#L10##C0xF76B45#【Pokémon Assembly】",
		fmt_th = "#L10##C0xF76B45#【Pokémon Assembly】",
		fmt_en = "#L10##C0xF76B45#【Pokémon Assembly】"
	},
	[135308] = {
		id = 135308,
		fmt = "1. Rare and above Pokémon can be equipped with contracts. After obtaining the Pokémon, you can go to the contract interface to select and view them.",
		fmt_th = "1. Rare and above Pokémon can be equipped with contracts. After obtaining the Pokémon, you can go to the contract interface to select and view them.",
		fmt_en = "1. Rare and above Pokémon can be equipped with contracts. After obtaining the Pokémon, you can go to the contract interface to select and view them."
	},
	[135309] = {
		id = 135309,
		fmt = "2.#C0xF76B45#Each Pokémon is set with a contract assembly field. The field also has a type setting. Contracts of the same type need to be assembled, and the same contract is repeatedly assembled on an Pokémon. The assembly does not set the quality.",
		fmt_th = "2.#C0xF76B45#Each Pokémon is set with a contract assembly field. The field also has a type setting. Contracts of the same type need to be assembled, and the same contract is repeatedly assembled on an Pokémon. The assembly does not set the quality.",
		fmt_en = "2.#C0xF76B45#Each Pokémon is set with a contract assembly field. The field also has a type setting. Contracts of the same type need to be assembled, and the same contract is repeatedly assembled on an Pokémon. The assembly does not set the quality."
	},
	[135310] = {
		id = 135310,
		fmt = "3. Depending on the rarity of the Pokémon, the number of slots in the equipment contract is also different.",
		fmt_th = "3. Depending on the rarity of the Pokémon, the number of slots in the equipment contract is also different.",
		fmt_en = "3. Depending on the rarity of the Pokémon, the number of slots in the equipment contract is also different."
	},
	[135311] = {
		id = 135311,
		fmt = "4. #C0xF76B45# The Pokémon’s slot needs to meet the unlocking conditions before it can be unlocked and used. If the Pokémon’s other development content changes after the slot is unlocked, the slot will be blocked again and the assembled contract will be removed. , wait until the conditions are met again to open. If you consume resources to unlock the slot, you will not be required to consume resources again.",
		fmt_th = "4. #C0xF76B45# The Pokémon’s slot needs to meet the unlocking conditions before it can be unlocked and used. If the Pokémon’s other development content changes after the slot is unlocked, the slot will be blocked again and the assembled contract will be removed. , wait until the conditions are met again to open. If you consume resources to unlock the slot, you will not be required to consume resources again.",
		fmt_en = "4. #C0xF76B45# The Pokémon’s slot needs to meet the unlocking conditions before it can be unlocked and used. If the Pokémon’s other development content changes after the slot is unlocked, the slot will be blocked again and the assembled contract will be removed. , wait until the conditions are met again to open. If you consume resources to unlock the slot, you will not be required to consume resources again."
	},
	[135312] = {
		id = 135312,
		fmt = "5.#C0xF76B45#When a Pokémon's rarity changes due to super evolution, the number of Pokémon slots and configurations may change. After the change, the assembly information for the same slot will be retained, while different slots will be locked again. Equipped contracts will be removed, and resources spent on unlocking slots prior to this change will be refunded. Please go to your mailbox to collect the resources.",
		fmt_th = "5.#C0xF76B45#When a Pokémon's rarity changes due to super evolution, the number of Pokémon slots and configurations may change. After the change, the assembly information for the same slot will be retained, while different slots will be locked again. Equipped contracts will be removed, and resources spent on unlocking slots prior to this change will be refunded. Please go to your mailbox to collect the resources.",
		fmt_en = "5.#C0xF76B45#When a Pokémon's rarity changes due to super evolution, the number of Pokémon slots and configurations may change. After the change, the assembly information for the same slot will be retained, while different slots will be locked again. Equipped contracts will be removed, and resources spent on unlocking slots prior to this change will be refunded. Please go to your mailbox to collect the resources."
	},
